    local changedCommand = SurvivorCompanion.Positioning.followMode(
        "sneak", 0, 5, player, 3, committedFollower, 43)
    check(stealthRun == "jog" and stealthCommitted == "jog"
            and stealthExpired == "sneak" and stealthStillActive == false
