do
    local movingGoalActor = actor("sc-moving-goal-stuck", -5, 4, {})
    registry[movingGoalActor.id] = movingGoalActor
    check(SurvivorCompanion.Navigation.request(
        movingGoalActor,
        squares[squareKey(-2, 4, 0)],
