local stagedReader = actor("sc-staged-reader", 8, 4,
    { inventory = inventory({ stagedBook }) })
stagedReader.square.room = { name = "safe_room" }
stagedReader.modData.SC_Order = "stay"
stagedReader.modData.SC_WorkMode = "idle"
