    end,
    clearVisual = function(value)
        visualStates[value] = "none"
    end,
    cancelVisual = function(value)
        visualStates[value] = "cancelled"
        visualCancels[value] = (visualCancels[value] or 0) + 1
        return true
    end,
    stopDirect = function(value)
        value.moving = false
        return true
    end,
}

