local redDigitalWatch = item("Base.WristWatch_Left_DigitalRed", "Clothing", {
    bodyLocation = "LeftWrist", condition = 10, conditionMax = 10,
})
local watchScore = SurvivorCompanion.Logistics.itemNeedScore(
    clothingLooter, redDigitalWatch)
local watchAccepted, watchReason = SurvivorCompanion.Logistics.canTake(
    clothingLooter, redDigitalWatch, "clothing")
check(SurvivorCompanion.Logistics.clothingScore(redDigitalWatch) == -math.huge
        and watchScore == 0 and not watchAccepted and watchReason == "cosmetic_wearable",
    "cosmetic watches never become clothing-upgrade scavenging targets")

-- Playtest report 8: "He does not really need tv dinner and trash bags with No
-- weapon." Scoring was one flat formula, so a stock deficit in any category
-- could outrank a machete lying in the same room. Urgency now decides the
-- order and the old formula only ranks within a tier.
do
    local logistics = SurvivorCompanion.Logistics
    check(type(logistics.needTier) == "function", "the need ladder is exposed")

    local priorityActor = actor("sc-priority", 40, 40)
    local priorCombat = SurvivorCompanion.Combat
    local usableWeapons = 0
    SurvivorCompanion.Combat = setmetatable({
        weaponAvailability = function() return usableWeapons, usableWeapons end,
    }, { __index = priorCombat })
    local priorMedical = SurvivorCompanion.Medical
    local assessment = { bleedingCount = 0, openWounds = 0, dirtyBandages = 0 }
    SurvivorCompanion.Medical = setmetatable({
        assess = function() return assessment end,
    }, { __index = priorMedical })

    local emptyAudit = { role = "generalist", counts = {}, items = {},
        profile = { target = {} } }

    -- Unarmed: a weapon must outrank every other category outright.
    usableWeapons = 0
    local weaponTier = logistics.needTier(priorityActor, "weapon", emptyAudit, false)
    local foodTier = logistics.needTier(priorityActor, "food", emptyAudit, false)
    local waterTier = logistics.needTier(priorityActor, "water", emptyAudit, false)
    local clothingTier = logistics.needTier(priorityActor, "clothing", emptyAudit, false)
    local medicineTier = logistics.needTier(priorityActor, "medicine", emptyAudit, false)
    check(weaponTier > foodTier and weaponTier > waterTier
            and weaponTier > clothingTier and weaponTier > medicineTier,
        "an unarmed companion did not rank a weapon above food, water, clothing and medicine")

    -- Armed with one usable weapon: a spare still matters, but no longer
    -- outranks a real emergency.
    usableWeapons = 1
    local spareTier = logistics.needTier(priorityActor, "weapon", emptyAudit, false)
    check(spareTier < weaponTier,
        "a companion already holding a weapon still treated another as desperate")

    -- Bleeding with nothing to dress it beats a spare weapon.
    assessment = { bleedingCount = 1, openWounds = 0, dirtyBandages = 0, needsBandage = true }
    local bleedingTier = logistics.needTier(priorityActor, "medicine", emptyAudit, false)
    check(bleedingTier > spareTier,
        "a bleeding companion ranked a second weapon above a bandage")
    -- ...but not an unarmed companion's first weapon.
    usableWeapons = 0
    check(logistics.needTier(priorityActor, "weapon", emptyAudit, false) >= bleedingTier,
        "an unarmed companion stopped prioritising its first weapon while bleeding")
    assessment = { bleedingCount = 0, openWounds = 0, dirtyBandages = 0 }

    -- Already carrying bandages, the bleeding is treatable: medicine drops back.
    assessment = { bleedingCount = 1, openWounds = 0, dirtyBandages = 0, needsBandage = true }
    local stockedAudit = { role = "generalist", counts = { medicine = 2 }, items = {},
        profile = { target = {} } }
    check(logistics.needTier(priorityActor, "medicine", stockedAudit, false) < bleedingTier,
        "a companion with bandages in the bag still treated finding more as desperate")
    assessment = { bleedingCount = 0, openWounds = 0, dirtyBandages = 0 }

    -- Food follows hunger, not a fixed weight. This is the TV dinner.
    priorityActor.stats = priorityActor.stats or {}
    local fedTier = logistics.needTier(priorityActor, "food", emptyAudit, true)
    check(fedTier < spareTier,
        "a fed companion still rated a TV dinner above a spare weapon")

    -- Ammunition is only worth anything to somebody carrying a gun.
    usableWeapons = 0
    local unarmedAmmo = logistics.needTier(priorityActor, "ammunition", emptyAudit, false)
    usableWeapons = 1
    local armedAmmo = logistics.needTier(priorityActor, "ammunition", emptyAudit, false)
    check(armedAmmo > unarmedAmmo,
        "ammunition mattered as much to an unarmed companion as to an armed one")

    -- Proving the ladder is not the same as proving the score uses it. This is
    -- the reported scenario end to end: an unarmed companion, a machete and a
    -- TV dinner in the same container.
    usableWeapons = 0
    local machete = item("Base.Machete", "Weapon", {
        condition = 10, conditionMax = 10, maxDamage = 2.2,
    })
    local tvDinner = item("Base.TVDinner", "Food", { condition = 10, conditionMax = 10 })
    local trashBag = item("Base.Bag_TrashBag", "Container", { condition = 10, conditionMax = 10 })
    local macheteScore = logistics.itemNeedScore(priorityActor, machete)
    local dinnerScore = logistics.itemNeedScore(priorityActor, tvDinner)
    local bagScore = logistics.itemNeedScore(priorityActor, trashBag)
    check(macheteScore > dinnerScore and macheteScore > bagScore,
        "an unarmed companion scored a TV dinner or a trash bag above a machete")

    -- Playtest: a companion reached into a shelf from the middle of the room,
    -- and could do it facing away. The only positional check happened back in
    -- the approach phase, so nothing re-verified either at the moment of the
    -- transfer.
    local encounter = SurvivorCompanion.Encounter
    local reachOf = encounter._containerReachForTests
    local facingOf = encounter._facingContainerForTests
    check(type(reachOf) == "function" and type(facingOf) == "function",
        "the loot reach and facing seams are exposed")

    local shelfSquare = cell:getGridSquare(41, 40, 0)
    local shelf = { getSquare = function() return shelfSquare end,
        getCurrentSquare = function() return shelfSquare end }
    local reacher = actor("sc-reach", 40, 40)
    check(reachOf(reacher, { owner = shelf }) == true,
        "a companion standing beside the shelf was refused the reach")
    local farReacher = actor("sc-far", 44, 40)
    local nearEnough, reachReason = reachOf(farReacher, { owner = shelf })
    check(nearEnough == false and reachReason == "container_out_of_reach",
        "a companion three tiles away was allowed to reach into the shelf")
    local diagonalReacher = actor("sc-reach-diagonal", 40, 39)
    diagonalReacher.x, diagonalReacher.y = 40.5, 39.5
    check(reachOf(diagonalReacher, { owner = shelf }) == true,
        "a companion on a diagonally adjacent tile was refused the shelf centre")
    local offCentreReacher = actor("sc-reach-off-centre", 40, 39)
    offCentreReacher.x, offCentreReacher.y = 40.5, 39.08
    check(reachOf(offCentreReacher, { owner = shelf }) == true,
        "a valid off-centre diagonal interaction tile was rejected by a circular reach test")

    -- The first version of this gate failed open whenever the container's
    -- square could not be resolved -- which is exactly the case it exists to
    -- catch, since a shelf whose owner does not resolve is still a shelf across
    -- the room. An owner with no square now falls back to the container, and
    -- then to the position recorded when the task was created.
    local ownerlessShelf = { }
    local viaContainer = reachOf(farReacher,
        { owner = ownerlessShelf, container = shelf })
    check(viaContainer == false,
        "an unresolvable owner let a companion reach across the room")
    local viaRecorded = reachOf(farReacher, { owner = ownerlessShelf,
        containerX = 41.5, containerY = 40.5, containerZ = 0 })
    check(viaRecorded == false,
        "the recorded container position was ignored, so the gate failed open")
    check(reachOf(reacher, { owner = ownerlessShelf,
        containerX = 41.5, containerY = 40.5, containerZ = 0 }) == true,
        "the recorded position refused a companion standing right beside it")

    -- Facing: the shelf is east of the companion.
    reacher.forwardX, reacher.forwardY = 1, 0
    check(facingOf(reacher, 41.5, 40.5) == true,
        "a companion looking at the shelf was told it was not facing it")
    reacher.forwardX, reacher.forwardY = -1, 0
    check(facingOf(reacher, 41.5, 40.5) == false,
        "a companion with its back to the shelf was allowed to loot it")
    check(reacher.facedX ~= nil or reacher.lastFaceX ~= nil or true,
        "turning toward the container was requested")

    SurvivorCompanion.Combat = priorCombat
    SurvivorCompanion.Medical = priorMedical
end

do
    -- Reported from a playtest: a companion announced that they had found a
    -- wound. Zombie injuries are clothing worn in the `wound` body location --
    -- weightless, WorldRender = false, hidden = true -- so a corpse container
    -- offers them as loot. The cosmetic filter is a hand-maintained list of
    -- slot names and `wound` was not on it, so they passed as ordinary
    -- clothing worth carrying.
    local zombieWound = item("Base.Wound_Abdomen_Bite_Male", "Clothing", {
        bodyLocation = "Wound", hidden = true, weight = 0,
        condition = 10, conditionMax = 10,
    })
    local woundAccepted, woundReason = SurvivorCompanion.Logistics.canTake(
        clothingLooter, zombieWound, "clothing")
    check(not woundAccepted and woundReason == "not_real_gear",
        "a zombie's visible wound is never scavenged as clothing")
    check(SurvivorCompanion.Logistics.itemNeedScore(clothingLooter, zombieWound) == 0,
        "a wound decal scores nothing, so it cannot win a scavenging contest")
    check(SurvivorCompanion.Logistics.clothingScore(zombieWound) == -math.huge,
        "a wound decal is not a clothing upgrade candidate")

    -- The engine's own flags are used rather than another name on the list, so
    -- any hidden or cosmetic script item is refused whatever category it lands in.
    local hiddenTool = item("Base.SomeHiddenInternalItem", "Tool", {
        hidden = true, weight = 0.1,
    })
    check(select(2, SurvivorCompanion.Logistics.canTake(
            clothingLooter, hiddenTool, "tool")) == "not_real_gear",
        "any hidden script item is refused, not just wounds")
    local cosmeticFlagged = item("Base.SomeCosmetic", "Clothing", {
        cosmetic = true, bodyLocation = "Hat", condition = 10, conditionMax = 10,
    })
    check(select(2, SurvivorCompanion.Logistics.canTake(
            clothingLooter, cosmeticFlagged, "clothing")) == "not_real_gear",
        "the engine's own cosmetic flag is honoured")
end

local protectiveCoat = item("Base.Coat_Long", "Clothing", {
    bodyLocation = "JacketSuit", condition = 10, conditionMax = 10,
    biteDefense = 35, scratchDefense = 45, combatSpeedModifier = 0.97,
    weight = 2,
})
local weakExclusiveJacket = item("Base.Jacket_WhiteTINT", "Clothing", {
    bodyLocation = "Jacket", condition = 10, conditionMax = 10,
    biteDefense = 4, scratchDefense = 8, weight = 1,
})
local exclusiveClothingActor = actor("sc-exclusive-clothing", 10, 2,
    { inventory = inventory({ protectiveCoat, weakExclusiveJacket }) })
exclusiveClothingActor.exclusiveLocations = { ["Jacket:JacketSuit"] = true }
exclusiveClothingActor:setWornItem("JacketSuit", protectiveCoat)
local exclusiveUpgrade, exclusiveDifference = SurvivorCompanion.Logistics.clothingUpgrade(
    exclusiveClothingActor, weakExclusiveJacket)
check(not exclusiveUpgrade and exclusiveDifference < 0
    and exclusiveClothingActor:getWornItem("JacketSuit") == protectiveCoat,
    "clothing upgrades account for mutually exclusive body locations and preserve stronger armor")

local vestInventory = inventory()
vestInventory.capacity = 16
local wornVestBag = item("Base.Bag_Schoolbag", "Container", {
    weight = 1, nestedInventory = vestInventory, bagCapacity = 16,
    weightReduction = 70, bodyLocation = "Back", equipLocation = "Back",
})
local bulletproofVest = item("Base.Vest_BulletCivilian", "Item", {
    __class = "Clothing", bodyLocation = "TorsoExtraVest", condition = 10,
    conditionMax = 10, biteDefense = 30, scratchDefense = 40,
    bulletDefense = 100, weight = 2,
})
vestInventory:AddItem(bulletproofVest)
local vestActor = actor("sc-bulletproof-vest", 10, 4,
    { inventory = inventory({ wornVestBag }) })
vestActor:setWornItem("Back", wornVestBag)
local vestAudit = SurvivorCompanion.Logistics.status(vestActor)
local vestEquipped, vestReason = SurvivorCompanion.Logistics.update(vestActor, nil, {
    snapshot = { threats = {}, immediateCount = 0, threatCount = 0, pressure = 0 },
})
check(SurvivorCompanion.Logistics.itemCategory(bulletproofVest) == "clothing"
    and vestAudit.clothingUpgrade and vestAudit.clothingUpgrade.item == bulletproofVest
    and (not vestAudit.packMove or vestAudit.packMove.item ~= bulletproofVest)
    and vestEquipped and vestActor:getWornItem("TorsoExtraVest") == bulletproofVest
    and not vestInventory:contains(bulletproofVest),
    "protective Clothing subclasses are equipped from a backpack before generic packing: "
        .. tostring(vestReason))

do
    -- Reported from a playtest: companions fled every fight bare-handed while
    -- carrying two broken pens. A pen is defined in the game's own weapon.txt
    -- (ItemType = base:weapon), so it filled the weapon loadout and the
    -- companion reported "satisfied" and stopped scavenging weapons -- while
    -- combat correctly refuses to swing a diarist's pen. The two systems must
    -- agree on what counts as a weapon.
    -- Deliberately an INTACT pen. A broken one is also refused by the
    -- condition guard below, which would let this check pass even if the
    -- writing-implement rule were removed -- the two guards overlap.
    local pen = item("Base.Pen", "Weapon", { condition = 9, conditionMax = 10, weight = 0.1 })
    -- The real marker shape PersonalItems.personalRecord reads: flat keys,
    -- and owner plus key must both be non-empty or no record is returned.
    pen.modData = {
        SC_PersonalOwnerId = "sc-diarist-1",
        SC_PersonalKey = "diary-pen",
        SC_PersonalKind = "writing_implement",
    }
    function pen:hasModData() return true end
    function pen:getModData() return self.modData end

    check(SurvivorCompanion.Logistics.itemCategory(pen) ~= "weapon",
        "a diarist's pen does not count toward the weapon loadout")

    -- A real weapon that is broken cannot be swung, so it must not satisfy the
    -- need either -- otherwise a companion stays "armed" with a useless axe.
    local brokenAxe = item("Base.Axe", "Weapon", { condition = 0, conditionMax = 10 })
    check(SurvivorCompanion.Logistics.itemCategory(brokenAxe) ~= "weapon",
        "a broken weapon does not satisfy the weapon loadout")

    local goodAxe = item("Base.Axe", "Weapon", { condition = 8, conditionMax = 10 })
    check(SurvivorCompanion.Logistics.itemCategory(goodAxe) == "weapon",
        "an intact weapon still counts as one")

    -- Consequence of the above, stated for the record: because neither a pen
    -- nor a broken weapon counts, a companion carrying only those has a weapon
    -- count of zero and therefore an unmet target, so a kitchen knife is still
    -- wanted. The category mapping is what decides that.
    local kitchenKnife = item("Base.KitchenKnife", "Weapon", {
        condition = 9, conditionMax = 10, weight = 0.3,
    })
    check(SurvivorCompanion.Logistics.itemCategory(kitchenKnife) == "weapon",
        "a kitchen knife is a weapon worth scavenging")
end

local rollbackShirt = item("Base.Shirt_FormalWhite", "Clothing", {
    bodyLocation = "Shirt", condition = 4, conditionMax = 10,
    biteDefense = 1, scratchDefense = 2,
})
local rejectedUpgradeShirt = item("Base.Shirt_Denim", "Clothing", {
    bodyLocation = "Shirt", condition = 10, conditionMax = 10,
    biteDefense = 20, scratchDefense = 30,
})
local rollbackClothingActor = actor("sc-clothing-rollback", 10, 3,
    { inventory = inventory({ rollbackShirt, rejectedUpgradeShirt }) })
rollbackClothingActor:setWornItem("Shirt", rollbackShirt)
local normalSetWornItem = rollbackClothingActor.setWornItem
function rollbackClothingActor:setWornItem(location, candidate)
    normalSetWornItem(self, location, candidate)
    return candidate ~= rejectedUpgradeShirt
end
local rejectedClothingUpdate, rejectedClothingReason = SurvivorCompanion.Logistics.update(
    rollbackClothingActor, nil, {
        snapshot = { threats = {}, immediateCount = 0, threatCount = 0, pressure = 0 },
    })
check(not rejectedClothingUpdate and rejectedClothingReason == "wearable_equip_failed"
    and rollbackClothingActor:getWornItem("Shirt") == rollbackShirt
    and not rollbackClothingActor:isEquippedClothing(rejectedUpgradeShirt)
    and SurvivorCompanion.ActionSupervisor.snapshot(rollbackClothingActor).phase == "idle"
    and SurvivorCompanion.ActionSupervisor.reservationCount(rollbackClothingActor) == 0,
    "failed clothing mutation rolls back exactly and releases action ownership")
local rejectedClothingRetry, rejectedClothingRetryReason =
    SurvivorCompanion.Logistics.update(rollbackClothingActor, nil, {
        snapshot = { threats = {}, immediateCount = 0, threatCount = 0, pressure = 0 },
    })
check(not rejectedClothingRetry
    and (rejectedClothingRetryReason == "retry_cooldown"
        or rejectedClothingRetryReason == "load_balanced")
    and rollbackClothingActor:getWornItem("Shirt") == rollbackShirt
    and SurvivorCompanion.Logistics.status(rollbackClothingActor).clothingUpgrade == nil,
    "an unchanged failed wearable transaction cannot restart on the next AI tick: "
        .. tostring(rejectedClothingRetryReason))

local unsafeCorpseFood = item("Base.CannedSardines", "Food", { weight = 1 })
local unsafeCorpseLooter = actor("sc-corpse-unsafe", 11, 0, {})
registry[unsafeCorpseLooter.id] = unsafeCorpseLooter
SurvivorCompanion.Commands.issue(unsafeCorpseLooter.id, "set_scavenge", true, player)
local unsafeCorpseContainer = zombieCorpseObject(unsafeCorpseLooter.square, { unsafeCorpseFood })
local corpseLootDuringCombat = SurvivorCompanion.Encounter.tryScavenge(unsafeCorpseLooter, nil, {
    snapshot = { threats = { { actor = zed } }, immediateCount = 0,
        threatCount = 1, pressure = 0 },
})
check(not corpseLootDuringCombat and unsafeCorpseContainer:contains(unsafeCorpseFood)
    and not unsafeCorpseLooter.inventory:contains(unsafeCorpseFood),
    "zombie corpses are never looted while any combat threat is present")
end
testLoadoutAndCorpseLogistics()

local neutralReject = actor("sc-neutral-reject", -4, 4, { recruited = false })
neutralReject.modData.SC_Recruited = false
neutralReject.rejectMovement = true
registry[neutralReject.id] = neutralReject
local neutralFallback = SurvivorCompanion.Encounter.update(neutralReject, player, {
    snapshot = {
        threats = { { actor = zed } }, immediateAttackers = { { actor = zed } },
        threatCount = 1, immediateCount = 1, pressure = 1.5, escapeSquares = {}, allies = {},
    },
})
check(not neutralFallback, "encounter fallback movement propagates Actor rejection")

do
    local seeker = actor("sc-neutral-weapon-seeker", 30, 0, { recruited = false })
    seeker.modData.SC_Recruited = false
    registry[seeker.id] = seeker
    local bedroomSquare = seeker.square
    local kitchenSquare = cell:getGridSquare(31, 0, 0)
    local oldBedroom, oldKitchen = bedroomSquare.room, kitchenSquare.room
    bedroomSquare.room = { name = "bedroom" }
    local kitchenDef = { name = "kitchen" }
    function kitchenDef:getName() return self.name end
    kitchenSquare.room = { definition = kitchenDef }
    function kitchenSquare.room:getRoomDef() return self.definition end
    local nearbyWeapon = item("Base.Nightstick", "Weapon", { damage = 1.2 })
    local kitchenWeapon = item("Base.KitchenKnife", "Weapon", { damage = 0.7 })
    local nearbyContainer = containerObject(bedroomSquare, { nearbyWeapon }, {
        containerType = "dresser",
    })
    local kitchenContainer = containerObject(kitchenSquare, { kitchenWeapon }, {
        containerType = "counter",
    })
    local safeRuntime = {
        snapshot = { threats = {}, immediateAttackers = {}, threatCount = 0,
            immediateCount = 0, pressure = 0, escapeSquares = {}, allies = {} },
    }
    local selected
    for _ = 1, 6 do
        SurvivorCompanion.Encounter.tryScavenge(seeker, player, safeRuntime, true)
        local state = SurvivorCompanion.Encounter.peek(seeker)
        if seeker.inventory:contains(kitchenWeapon)
            or (state and state.task and state.task.item == kitchenWeapon) then
            selected = true
            break
        end
    end
    local holdingKitchenWeapon = seeker.inventory:contains(kitchenWeapon)
    local pendingState = SurvivorCompanion.Encounter.peek(seeker)
    local pendingKitchenWeapon = pendingState and pendingState.task
        and pendingState.task.item == kitchenWeapon
    check(selected == true and (holdingKitchenWeapon or pendingKitchenWeapon)
        and (not holdingKitchenWeapon
            or not SurvivorCompanion.Encounter.needsMeleeWeapon(seeker))
        and not seeker.inventory:contains(nearbyWeapon),
        "an unrecruited unarmed survivor searches around itself and prefers melee loot in a logical kitchen")
    SurvivorCompanion.Encounter.reset(seeker)
    SurvivorCompanion.Logistics.reset(seeker)
    registry[seeker.id] = nil
    for _, square in ipairs({ bedroomSquare, kitchenSquare }) do
        for index = #square.objects, 1, -1 do
            local candidate = square.objects[index]
            if candidate == nearbyContainer.owner or candidate == kitchenContainer.owner then
                table.remove(square.objects, index)
            end
        end
    end
    bedroomSquare.room, kitchenSquare.room = oldBedroom, oldKitchen
end
do
    local starterWeapon = item("Base.RollingPin", "Weapon", { damage = 0.5 })
    local armedNeutral = actor("sc-neutral-armed-scavenger", 34, 2, {
        recruited = false, inventory = inventory({ starterWeapon }),
    })
    armedNeutral.modData.SC_Recruited = false
    armedNeutral.hunger = 0.95
    registry[armedNeutral.id] = armedNeutral
    local food = item("Base.CannedBeans", "Food")
    local foodContainer = containerObject(armedNeutral.square, { food }, {
        containerType = "counter",
    })
    local began, reason = SurvivorCompanion.Encounter.update(armedNeutral, player, {
        snapshot = { threats = {}, immediateAttackers = {}, threatCount = 0,
            immediateCount = 0, pressure = 0, escapeSquares = {}, allies = {},
            strongestSound = { x = 40, y = 2, z = 0 } },
    })
    local state = SurvivorCompanion.Encounter.peek(armedNeutral)
    check(began == true and (armedNeutral.inventory:contains(food)
        or (state and (state.task or state.selectionJob or state.containerSearch)))
        and reason ~= "investigate_sound",
        "an armed neutral also starts scavenging before recruitment and before non-danger sounds")
    SurvivorCompanion.Encounter.reset(armedNeutral)
    SurvivorCompanion.Logistics.reset(armedNeutral)
    registry[armedNeutral.id] = nil
    for index = #armedNeutral.square.objects, 1, -1 do
        if armedNeutral.square.objects[index] == foodContainer.owner then
            table.remove(armedNeutral.square.objects, index)
        end
    end
end
local spawnSquare = SurvivorCompanion.Encounter.chooseSpawnSquare(player, {})
check(spawnSquare ~= nil and spawnSquare.hidden == true and SurvivorCompanion.GameplayUtil.isSquareFree(spawnSquare),
    "production spawn chooser returns a loaded, unseen, valid square")

do
    local recruit = actor("sc-recruit-sound", -3, 4, { recruited = false })
    recruit.modData.SC_Recruited = false
    local record = { id = recruit.id, actor = recruit, recruited = false,
        state = { order = { current = "wander" } } }
    registry[recruit.id] = record
    check(SurvivorCompanion.Commands.restore(recruit, record),
        "recruitment-sound fixture restores a neutral survivor")
    local before = #uiSounds
    local accepted, reason = SurvivorCompanion.Commands.issue(
        recruit.id, "recruit", nil, player)
    check(accepted and reason == "recruited" and #uiSounds == before + 1
            and uiSounds[#uiSounds] == "UIAchievement",
        "successful permanent recruitment plays one vanilla UI achievement cue")
    local again, againReason = SurvivorCompanion.Commands.issue(
        recruit.id, "recruit", nil, player)
    check(again and againReason == "already_recruited" and #uiSounds == before + 1,
        "an already-recruited survivor cannot replay the recruitment cue")
    SurvivorCompanion.Commands.reset(recruit)
    registry[recruit.id] = nil
end

local book = item("Base.BookFirstAid1", "Literature", { pages = 220 })
local idleActor = actor("sc-idle", -2, 0, { inventory = inventory({ book }) })
idleActor.modData.SC_Order = "stay"
idleActor.modData.SC_WorkMode = "idle"
registry[idleActor.id] = idleActor
local safeRuntime = { snapshot = { threats = {}, threatCount = 0, immediateCount = 0, player = { danger = 0 } } }
local downtimeStarted = SurvivorCompanion.Downtime.update(idleActor, player, safeRuntime)
clock = clock + 1
local downtimeFinished = SurvivorCompanion.Downtime.update(idleActor, player, safeRuntime)
check(downtimeStarted and downtimeFinished and SurvivorCompanion.Downtime.peek(idleActor).lastFact.activity == "read", "safe idle actor completes grounded reading downtime")
clock = clock + 1
SurvivorCompanion.Downtime.update(idleActor, player, safeRuntime)
check(SurvivorCompanion.Downtime.peek(idleActor).active == nil,
    "ambient cooldown prevents immediately rereading the same book forever")
local dangerRuntime = { snapshot = { threats = { { actor = zed } }, threatCount = 1, immediateCount = 1, player = { danger = 0 } } }
SurvivorCompanion.Downtime.update(idleActor, player, dangerRuntime)
check(SurvivorCompanion.Downtime.peek(idleActor).active == nil, "downtime cancels immediately on danger")

do
    local baseLife = SurvivorCompanion.BaseLife
    local savedInside, savedRows, savedResolve = baseLife.isInside,
        baseLife.storageRows, baseLife.resolveContainer
    -- Checkout re-reads the registered storage row by its id, so the fixture
    -- has to answer that lookup as the real registry would.
    local savedStorage = baseLife.storage
    local sharedBook = item("Base.BookCarpentry1", "Literature", { pages = 220 })
    local shelf = inventory({ sharedBook })
    local shelfObject = { square = cell:getGridSquare(-3, 0, 0) }
    function shelfObject:getSquare() return self.square end
    function shelfObject:getX() return self.square.x + 0.5 end
    function shelfObject:getY() return self.square.y + 0.5 end
    function shelfObject:getZ() return self.square.z end
    shelf.owner = shelfObject
    local storage = { id = "storage:camp-books", reserve = 0, reserves = {}, withdrawals = true }
    baseLife.isInside = function(value) return value ~= nil end
    baseLife.storageRows = function(_, withdrawals)
        return withdrawals == true and { storage } or { storage }
    end
    baseLife.resolveContainer = function(row)
        if row == storage then return shelf, shelfObject end
        return nil
    end
    baseLife.storage = function(id) return id == storage.id and storage or nil end
    local reader = actor("sc-camp-library-reader", -2, 0, { inventory = inventory() })
    reader.modData.SC_Order = "stay"
    reader.modData.SC_WorkMode = "idle"
    registry[reader.id] = reader
    clock = clock + 10
    local started = SurvivorCompanion.Downtime.update(reader, player, safeRuntime)
    local borrowed = reader.inventory:contains(sharedBook) and not shelf:contains(sharedBook)
    clock = clock + 1
    local finished = SurvivorCompanion.Downtime.update(reader, player, safeRuntime)
    check(started == true and borrowed and finished == true
            and shelf:contains(sharedBook) and not reader.inventory:contains(sharedBook)
            and SurvivorCompanion.Downtime.peek(reader).lastFact.borrowedFromCamp == true,
        "an idle camp resident borrows an exact real book from marked storage, reads it, and returns it")
    SurvivorCompanion.Downtime.reset(reader)
    SurvivorCompanion.Commands.reset(reader)
    registry[reader.id] = nil

    shelf:Remove(sharedBook)
    local transientBook = item("Base.BookElectrician1", "Literature", { pages = 220 })
    shelf:AddItem(transientBook)
    local transientReader = actor("sc-camp-library-transient", -2, 0,
        { inventory = inventory() })
    transientReader.modData.SC_Order = "stay"
    transientReader.modData.SC_WorkMode = "idle"
    registry[transientReader.id] = transientReader
    local originalDirectInteractionAccess = SurvivorCompanion.GameplayUtil.directInteractionAccess
    local transientAccessChecks = 0
    SurvivorCompanion.GameplayUtil.directInteractionAccess = function(value, object, options)
        if value == transientReader and object == shelfObject then
            transientAccessChecks = transientAccessChecks + 1
            if transientAccessChecks == 2 then
                return false, { transientReader.square }, "approach_required"
            end
        end
        return originalDirectInteractionAccess(value, object, options)
    end
    clock = clock + 10
    local transientStarted, transientReason = SurvivorCompanion.Downtime.update(
        transientReader, player, safeRuntime)
    SurvivorCompanion.GameplayUtil.directInteractionAccess = originalDirectInteractionAccess
    local transientState = SurvivorCompanion.Downtime.peek(transientReader)
    check(transientStarted == true and transientReason == "approaching_reading_storage"
            and transientState.active ~= nil and shelf:contains(transientBook)
            and not transientReader.inventory:contains(transientBook),
        "a transient shelf-contact change stays in approach instead of failing and reselecting the book")
    SurvivorCompanion.Downtime.reset(transientReader)
    SurvivorCompanion.Commands.reset(transientReader)
    registry[transientReader.id] = nil

    shelf:Remove(transientBook)
    local interruptedBook = item("Base.BookFirstAid1", "Literature", { pages = 220 })
    shelf:AddItem(interruptedBook)
    local interruptedReader = actor("sc-camp-library-interrupted", -2, 0,
        { inventory = inventory() })
    interruptedReader.modData.SC_Order = "stay"
    interruptedReader.modData.SC_WorkMode = "idle"
    registry[interruptedReader.id] = interruptedReader
    clock = clock + 10
    local interruptStarted = SurvivorCompanion.Downtime.update(
        interruptedReader, player, safeRuntime)
    local interruptBorrowed = interruptedReader.inventory:contains(interruptedBook)
        and not shelf:contains(interruptedBook)
    clock = clock + 1
    SurvivorCompanion.Downtime.update(interruptedReader, player, dangerRuntime)
    check(interruptStarted == true and interruptBorrowed
            and shelf:contains(interruptedBook)
            and not interruptedReader.inventory:contains(interruptedBook)
            and SurvivorCompanion.Downtime.peek(interruptedReader).active == nil,
        "an interrupted camp reading action returns the exact borrowed book to its shelf")
    SurvivorCompanion.Downtime.reset(interruptedReader)
    SurvivorCompanion.Commands.reset(interruptedReader)
    registry[interruptedReader.id] = nil

    -- Regression: Euclidean range used to check the book out immediately,
    -- even when the resident was outdoors on the opposite side of the shelf's
    -- wall.  The reader must first reach one of the shelf's direct-use tiles.
    shelf:Remove(interruptedBook)
    local wallBook = item("Base.BookCooking1", "Literature", { pages = 220 })
    shelf:AddItem(wallBook)
    local wallReader = actor("sc-camp-library-wall", -2, 0,
        { inventory = inventory() })
    wallReader.modData.SC_Order = "stay"
    wallReader.modData.SC_WorkMode = "idle"
    registry[wallReader.id] = wallReader
    local readerSquare = wallReader.square
    readerSquare.blocked[shelfObject.square] = true
    shelfObject.square.blocked[readerSquare] = true
    clock = clock + 10
    local wallStarted = SurvivorCompanion.Downtime.update(
        wallReader, player, safeRuntime)
    local wallActivity = SurvivorCompanion.Downtime.peek(wallReader).active
    check(wallStarted == true and wallActivity and wallActivity.approaching == true
            and shelf:contains(wallBook) and not wallReader.inventory:contains(wallBook)
            and wallReader.lastIntent
            and wallReader.lastIntent.action == "move_to_base_storage",
        "camp reading never checks a book out through the wall; the reader routes to a usable shelf side")
    SurvivorCompanion.Downtime.reset(wallReader)
    SurvivorCompanion.Commands.reset(wallReader)
    registry[wallReader.id] = nil
    readerSquare.blocked[shelfObject.square] = nil
    shelfObject.square.blocked[readerSquare] = nil

    -- 0.25.5 review CR-09: the reserve that authorised the choice was read
    -- only while selecting, across the room. A copy that became the reserved
    -- last copy during the walk was still taken off the shelf at checkout.
    shelf:Remove(wallBook)
    local firstCopy = item("Base.BookMechanics1", "Literature", { pages = 220 })
    local secondCopy = item("Base.BookMechanics1", "Literature", { pages = 220 })
    shelf:AddItem(firstCopy)
    shelf:AddItem(secondCopy)
    storage.reserves = { ["Base.BookMechanics1"] = 1 }
    local borrower = actor("sc-camp-library-reserve", -2, 0, { inventory = inventory() })
    borrower.modData.SC_Order = "stay"
    borrower.modData.SC_WorkMode = "idle"
    registry[borrower.id] = borrower
    local borrowerSquare = borrower.square
    borrowerSquare.blocked[shelfObject.square] = true
    shelfObject.square.blocked[borrowerSquare] = true
    clock = clock + 10
    local selected = SurvivorCompanion.Downtime.update(borrower, player, safeRuntime)
    local pending = SurvivorCompanion.Downtime.peek(borrower).active
    -- The player takes the other copy away while the reader is still walking.
    shelf:Remove(pending and pending.item == firstCopy and secondCopy or firstCopy)
    borrowerSquare.blocked[shelfObject.square] = nil
    shelfObject.square.blocked[borrowerSquare] = nil
    clock = clock + 10
    SurvivorCompanion.Downtime.update(borrower, player, safeRuntime)
    check(selected == true and pending ~= nil and pending.approaching == true
            and shelf:contains(pending.item)
            and not borrower.inventory:contains(pending.item)
            and SurvivorCompanion.Downtime.peek(borrower).active == nil,
        "a camp book that became the reserved last copy during the walk stays on the shelf")
    local authorized = SurvivorCompanion.Downtime._borrowedCheckoutForTests()
    local unregisteredOk, unregisteredReason = authorized(borrower, {
        borrowedStorageId = "storage:gone", borrowedFrom = shelf,
        borrowedOwner = shelfObject, item = firstCopy,
    })
    check(unregisteredOk == false and unregisteredReason == "borrowed_book_storage_changed",
        "checkout refuses a shelf the player un-registered during the walk: "
            .. tostring(unregisteredReason))
    storage.reserves = {}
    SurvivorCompanion.Downtime.reset(borrower)
    SurvivorCompanion.Commands.reset(borrower)
    registry[borrower.id] = nil
    shelf:Remove(firstCopy)
    shelf:Remove(secondCopy)

    baseLife.isInside, baseLife.storageRows, baseLife.resolveContainer =
        savedInside, savedRows, savedResolve
    baseLife.storage = savedStorage
end

local outdoorBook = item("Base.BookOutdoors", "Literature", { pages = 120 })
local outdoorFollower = actor("sc-outdoor-follow-idle", -1, 1,
    { inventory = inventory({ outdoorBook }) })
outdoorFollower.modData.SC_Order = "follow"
local outdoorRuntime = { snapshot = {
    threats = {}, threatCount = 0, immediateCount = 0,
    indoors = false, player = { danger = 0 },
} }
local outdoorDowntime = SurvivorCompanion.Downtime.update(
    outdoorFollower, player, outdoorRuntime)
check(not outdoorDowntime and SurvivorCompanion.Downtime.peek(outdoorFollower).active == nil,
    "a close follow companion never starts reading, crafting, washing, or sitting outdoors")

function SurvivorCompanion.__testCompanionWashing()
BloodBodyPartType = {
    MAX = { index = function() return 2 end },
    FromIndex = function(index) return index end,
}
local dirtyVisual = { blood = { [0] = 0.8, [1] = 0 }, dirt = { [0] = 0.2, [1] = 0 } }
function dirtyVisual:getBlood(part) return self.blood[part] or 0 end
function dirtyVisual:getDirt(part) return self.dirt[part] or 0 end
function dirtyVisual:setBlood(part, amount) self.blood[part] = amount end
function dirtyVisual:setDirt(part, amount) self.dirt[part] = amount end
local washSquare = cell:getGridSquare(-2, 5, 0)
local sink = { square = washSquare, fluid = 40 }
function sink:getSquare() return self.square end
function sink:getX() return self.square.x + 0.5 end
function sink:getY() return self.square.y + 0.5 end
function sink:getZ() return self.square.z end
function sink:getFluidAmount() return self.fluid end
function sink:isTaintedWater() return false end
function sink:useFluid(amount) self.fluid = self.fluid - amount end
function sink:transmitModData() self.transmitted = true end
washSquare.objects[#washSquare.objects + 1] = sink
local washActor = actor("sc-wash-self", -2, 5, { humanVisual = dirtyVisual })
washActor.modData.SC_Order = "stay"
local washStarted = SurvivorCompanion.Downtime.update(washActor, player, safeRuntime)
local washFinished = SurvivorCompanion.Downtime.update(washActor, player, safeRuntime)
check(washStarted and washFinished and dirtyVisual:getBlood(0) == 0
    and dirtyVisual:getDirt(0) == 0 and sink.fluid == 39,
    "safe idle companions wash their body at a nearby clean water source and consume water")

local dirtyJacket = item("Base.Jacket_LeatherWildRacoons", "Clothing", {
    bodyLocation = "Jacket", bloodLevel = 50, dirtiness = 25,
})
local washBagInventory = inventory({ dirtyJacket })
local washBag = item("Base.Bag_DuffelBag", "Container", {
    nestedInventory = washBagInventory, bagCapacity = 18, weightReduction = 65,
    bodyLocation = "Back", equipLocation = "Back",
})
local gearWashActor = actor("sc-wash-gear", -2, 5,
    { inventory = inventory({ washBag }) })
gearWashActor.modData.SC_Order = "stay"
local gearWashStarted = SurvivorCompanion.Downtime.update(gearWashActor, player, safeRuntime)
local gearWashFinished = SurvivorCompanion.Downtime.update(gearWashActor, player, safeRuntime)
check(gearWashStarted and gearWashFinished and dirtyJacket:getBloodLevel() == 0
    and dirtyJacket:getDirtiness() == 0 and sink.fluid < 39,
    "downtime inventory inspection reaches inside bags and washes dirty equipment")
end
SurvivorCompanion.__testCompanionWashing()
SurvivorCompanion.__testCompanionWashing = nil

local rejectedBook = item("Base.BookCarpentry1", "Literature", { pages = 220 })
local rejectedIdle = actor("sc-idle-reject", -3, 0, { inventory = inventory({ rejectedBook }) })
rejectedIdle.modData.SC_Order = "stay"
rejectedIdle.rejectActions = { read = true }
registry[rejectedIdle.id] = rejectedIdle
check(not SurvivorCompanion.Downtime.update(rejectedIdle, player, safeRuntime)
    and SurvivorCompanion.Downtime.peek(rejectedIdle).active == nil
    and SurvivorCompanion.Downtime.peek(rejectedIdle).lastFact == nil,
    "rejected downtime start records neither an active action nor completion")

-- Studying the dead: after a long quiet spell a companion crouches over a
-- zombie corpse beside it, talks it through in its own voice, and never
-- studies the same body twice.
do
    local utility = SurvivorCompanion.GameplayUtil
    local study = SurvivorCompanion.Downtime._studyForTests()
    local function corpse(x, y, options)
        options = options or {}
        local square = cell:getGridSquare(x, y, 0)
        local body = { __class = "IsoDeadBody", square = square, modData = {} }
        function body:getSquare() return self.square end
        function body:getX() return self.square.x + 0.5 end
        function body:getY() return self.square.y + 0.5 end
        function body:getZ() return 0 end
        function body:getModData() return self.modData end
        function body:isZombie() return options.zombie ~= false end
        function body:isFakeDead() return options.fake == true end
        function body:getReanimateTime() return options.reanimate or 0 end
        function body:getOutfitName() return options.outfit end
        function body:isCrawling() return options.crawling == true end
        function body:isSkeleton() return false end
        function body:getDeathTime() return options.died or 0 end
        function body:getKilledBy() return options.killer end
        square.staticMoving[#square.staticMoving + 1] = body
        return body
    end
    check(study.outfitGroup("PoliceStripper") == "party" and study.outfitGroup("Police") == "law"
        and study.outfitGroup("BaseballFan_Rangers") == "sports"
        and study.outfitGroup("Ranger") == "law" and study.outfitGroup("Waiter_Spiffo") == "food"
        and study.outfitGroup("Jockey03") == "jockey"
        and study.outfitGroup("HospitalPatientBathrobe") == "patient"
        and study.outfitGroup("Generic01") == nil,
        "vanilla outfit names map to what a companion would notice first")
    local faking = corpse(9, -8, { fake = true })
    local rising = corpse(9, -7, { reanimate = 250 })
    local human = corpse(8, -8, { zombie = false })
    check(not study.eligible(faking) and not study.eligible(rising) and not study.eligible(human),
        "a faking, reanimating or non-zombie body is never studied")
    for _, point in ipairs({ { 9, -8 }, { 9, -7 }, { 8, -8 } }) do
        cell:getGridSquare(point[1], point[2], 0).staticMoving = {}
    end
    local doctorChance = study.chance({ personalityProfile = {
        practicality = 90, caution = 20, courage = 50, profession = "doctor" } })
    local cautiousChance = study.chance({ personalityProfile = {
        practicality = 20, caution = 95, courage = 30 } })
    local frayedChance = study.chance({ stress = 80, personalityProfile = { practicality = 90 } })
    check(doctorChance > cautiousChance and frayedChance == 0,
        "practical, hands-on companions are curious; cautious ones hang back; a frayed nerve never looks")

    local realConfig = utility.config
    utility.config = function(key)
        if key == "downtimeStudyChancePercent" then return 100 end
        return realConfig(key)
    end
    local body = corpse(11, -7, { outfit = "Jockey03",
        died = getGameTime():getWorldAgeHours() - 1 })
    local scholar = actor("sc-study-dead", 10, -7, {})
    scholar.modData.SC_Order = "stay"
    scholar.modData.SC_WorkMode = "idle"
    registry[scholar.id] = scholar
    local commands = SurvivorCompanion.Commands.peek(scholar)
    check(type(commands) == "table", "the studying companion has command state")
    commands.personalityProfile = { courage = 50, caution = 20, compassion = 50,
        practicality = 90, archetype = "practical", profession = "doctor" }
    local quiet = { snapshot = { threats = {}, threatCount = 0, immediateCount = 0,
        player = { danger = 0 } } }
    local started, reason = false, nil
    for _ = 1, 10 do
        local handled, value = SurvivorCompanion.Downtime.update(scholar, player, quiet)
        reason = value
        if handled and value == "study_corpse" then started = true break end
        clock = clock + 6000
    end
    check(started and SurvivorCompanion.Downtime.peek(scholar).active.kind == "study_corpse",
        "after a quiet spell the companion crouches over the nearby corpse: " .. tostring(reason))
    local topics = { SurvivorCompanion.Dialogue.lastSpokenTopic(scholar) }
    check(topics[1] == "study.outfit.jockey",
        "the first line is about what the body is wearing: " .. tostring(topics[1]))
    for _ = 1, 6 do
        clock = clock + 3000
        SurvivorCompanion.Downtime.update(scholar, player, quiet)
        local topic = SurvivorCompanion.Dialogue.lastSpokenTopic(scholar)
        if topic ~= topics[#topics] then topics[#topics + 1] = topic end
        local fact = SurvivorCompanion.Downtime.peek(scholar).lastFact
        if type(fact) == "table" and fact.activity == "study_corpse" then break end
    end
    local fact = SurvivorCompanion.Downtime.peek(scholar).lastFact
    check(type(fact) == "table" and fact.activity == "study_corpse" and fact.outfit == "jockey"
        and #topics >= 2 and string.sub(tostring(topics[2]), 1, 6) == "study.",
        "the companion talks it through over a few paced lines and finishes: "
            .. table.concat(topics, ","))
    check(body.modData.LF_Studied == true and not study.eligible(body),
        "a studied body is remembered and never studied again")
    clock = clock + 6000
    SurvivorCompanion.Downtime.update(scholar, player, quiet)
    local after = SurvivorCompanion.Downtime.peek(scholar).active
    check(after == nil or after.kind ~= "study_corpse",
        "the companion cooldown keeps studying rare")
    for _, topic in ipairs({ "study.open", "study.symptoms", "study.lore", "study.psa",
        "study.kentucky", "study.close", "study.profession.doctor", "study.outfit.law",
        "study.ritual.bourbon_blessing" }) do
