check(SurvivorCompanion.Needs.update(sourceDrinker, player, {
        snapshot = { threats = {}, threatCount = 0, immediateCount = 0, pressure = 0 },
    }) and sourceDrinker.lastIntent and sourceDrinker.lastIntent.action == "drink_source"
    and sourceDrinker.lastIntent.object == cleanSink,
    "thirsty companion discovers a bounded clean sink/well source")
SurvivorCompanion.Encounter.takePlayerSupply = originalCampWater
check(not campWaterRequested,
    "a clean nearby sink is used before withdrawing bottled water from camp storage")

local campActor = actor("sc-camp-supply", 36, 20, {})
registry[campActor.id] = campActor
local campFood = item("Base.CampMeal", "Food", { hungerChange = -0.25 })
local campContainer = containerObject(campActor.square, { campFood })
check(SurvivorCompanion.Encounter.markPlayerOpened(campContainer),
    "player-opened camp storage is explicitly recorded")
local campStatus = SurvivorCompanion.Encounter.takePlayerSupply(
    campActor, "test_food", function(candidate) return candidate == campFood end,
    { snapshot = { immediateCount = 0, pressure = 0 } })
check(campStatus == "taken" and campActor.inventory:contains(campFood)
    and not campContainer:contains(campFood),
    "reserved camp-storage transfer is transactional and limited to the selected item")

local unknownStorageActor = actor("sc-unknown-storage", -50, -50, {})
registry[unknownStorageActor.id] = unknownStorageActor
local unknownFood = item("Base.UnknownMeal", "Food", { hungerChange = -0.25 })
local unknownContainer = containerObject(unknownStorageActor.square, { unknownFood })
local unknownStatus = SurvivorCompanion.Encounter.takePlayerSupply(
    unknownStorageActor, "unknown_test", function(candidate) return candidate == unknownFood end,
    { snapshot = { immediateCount = 0, pressure = 0 } })
check(unknownStatus == "missing" and unknownContainer:contains(unknownFood)
    and not unknownStorageActor.inventory:contains(unknownFood),
    "companions never reinterpret an unopened world container as player camp storage")

local builder = actor("sc-camp-builder", 38, 20, {})
registry[builder.id] = builder
local sharedKit = buildKit()
local workshopContainer = containerObject(builder.square, sharedKit)
SurvivorCompanion.Encounter.markPlayerOpened(workshopContainer)
for _ = 1, 4 do
    SurvivorCompanion.Logistics.prepareBuild(builder, builder.square,
        { immediateCount = 0, pressure = 0 }, "walk")
end
local buildReady = SurvivorCompanion.Logistics.prepareBuild(builder, builder.square,
    { immediateCount = 0, pressure = 0 }, "walk")
check(buildReady and #builder.inventory.items == 4 and #workshopContainer.items == 0,
    "build order gathers one hammer, plank, and two nails from visited camp storage")

clock = clock + 4000
local signalActor = actor("sc-silent-warning", 40, 20, {})
local signalPlayer = actor("signal-player", 40, 21, { className = "IsoPlayer", recruited = false })
signalPlayer.modData.SC_Recruited = false
signalActor.modData.SC_MoveMode = "walk"
signalActor.modData.SC_MoveModeVersion = 2
registry[signalActor.id] = signalActor
local distantThreat = zombie(46, 20, {})
local soundsBeforeSignal = worldSoundCount
local signalSnapshot = {
    threats = { { actor = distantThreat, distanceSq = 36, visible = true, score = 20 } },
    immediateAttackers = {}, threatCount = 1, immediateCount = 0, pressure = 0.35,
    escapeSquares = {}, allies = {}, player = { actor = signalPlayer, danger = 0 },
}
local signalRuntime = { snapshot = signalSnapshot }
local savedSignalNativeActions = SurvivorCompanion.NativeActions
local savedSignalSnapshot = SurvivorCompanion.Senses.snapshot
local savedSignalRefreshImmediate = SurvivorCompanion.Senses.refreshImmediate
SurvivorCompanion.Senses.snapshot = function(_, _, runtime) return runtime.snapshot end
SurvivorCompanion.Senses.refreshImmediate = function(_, _, snapshot) return snapshot end
local signalPacing
SurvivorCompanion.NativeActions = {
    activityStatus = function() return "none" end,
    beginPacing = function(value, source, options)
        signalPacing = {
            actor = value, source = source, startedAt = clock,
            untilAt = clock + (tonumber(options.minimumMs) or 0),
            commandSerial = tonumber(SurvivorCompanion.Commands.peek(value).commandSerial) or 0,
            interruptForFollow = options.interruptForFollow,
            holdReason = options.holdReason,
            shouldLook = (tonumber(options.lookChancePercent) or -1) > 0,
            stopped = true,
        }
        return true, "pacing_started", signalPacing
    end,
    pacingStatus = function(value, current)
        if signalPacing and signalPacing.actor == value
            and current < signalPacing.untilAt then return true, signalPacing end
        signalPacing = nil
        return false, nil
    end,
    cancelPacing = function()
        signalPacing = nil
        return true, "pacing_cancelled"
    end,
}
local signalHandled, signalReason = SurvivorCompanion.Decision.update(
    signalActor, signalPlayer, signalRuntime)
check(signalHandled and signalReason == "threat_signal"
    and signalActor.lastIntent and signalActor.lastIntent.action == "hand_signal"
    and signalActor.lastIntent.target == distantThreat
    and signalActor.lastIntent.facingTarget == distantThreat
    and signalActor.lastIntent.faceTargetBeforeEmote == true
    and signalActor.lastIntent.stableFacing == true
    and signalPacing and signalPacing.interruptForFollow == false
    and signalPacing.holdReason == "threat_signal" and signalPacing.shouldLook == false
    and worldSoundCount == soundsBeforeSignal
    and type(signalActor.lastSpeech) == "string"
    and ((SurvivorCompanion.Dialogue.lastSpokenTopic(signalActor) == "signal.one"
            and string.sub(signalActor.lastSpeech, 1, 1) == "*")
        or SurvivorCompanion.Dialogue.lastSpokenTopic(signalActor) == "recognition.local"),
    "visible distant danger faces the exact zombie and displays a silent freeze or recognition signal")
local signalMovementCalls = signalActor.movementCalls
clock = clock + 100
local signalHeld, signalHeldReason = SurvivorCompanion.Decision.update(
    signalActor, signalPlayer, signalRuntime)
check(signalHeld and signalHeldReason == "threat_signal"
        and signalActor.movementCalls == signalMovementCalls,
    "the short warning pose prevents follow/path input from turning away during the emote")
SurvivorCompanion.NativeActions = savedSignalNativeActions
clock = clock + 4000
signalActor.lastEmote = nil
local alternateDistantThreat = zombie(46, 21, {})
signalRuntime.snapshot = {
    threats = { { actor = alternateDistantThreat, distanceSq = 37,
        visible = true, score = 21 } },
    immediateAttackers = {}, threatCount = 1, immediateCount = 0, pressure = 0.35,
    escapeSquares = {}, allies = {}, player = { actor = signalPlayer, danger = 0 },
}
SurvivorCompanion.Decision.update(signalActor, signalPlayer, signalRuntime)
signalRuntime.snapshot = signalSnapshot
check(signalActor.lastEmote == nil
        and SurvivorCompanion.Dialogue.lastSpokenTopic(signalActor) == "signal.one",
    "a different top-ranked zombie cannot restart the same warning hand signal during cooldown")
SurvivorCompanion.Downtime.reset(signalActor)
SurvivorCompanion.Locomotion.reset(signalActor)
signalRuntime.snapshot = {
    threats = { { actor = distantThreat, distanceSq = 36, visible = true, score = 90 } },
    immediateAttackers = {}, threatCount = 12, immediateCount = 0, pressure = 1.2,
    escapeSquares = {}, allies = {}, player = { actor = signalPlayer, danger = 0 },
}
SurvivorCompanion.Decision.update(signalActor, signalPlayer, signalRuntime)
check(SurvivorCompanion.Dialogue.lastSpokenTopic(signalActor) == "signal.horde"
        and worldSoundCount == soundsBeforeSignal,
    "a contact escalating from one zombie to a horde bypasses the stale warning cooldown silently: topic="
        .. tostring(SurvivorCompanion.Dialogue.lastSpokenTopic(signalActor))
        .. " rank=" .. tostring(SurvivorCompanion.Decision.peek(signalActor).lastThreatBandRank)
        .. " intent=" .. tostring(SurvivorCompanion.Decision.peek(signalActor).intent))
clock = clock + 31000
signalActor.lastEmote = nil
local continuousWarningDeadline = SurvivorCompanion.Decision.peek(signalActor).nextThreatWarningAt
local continuousWarningRank = SurvivorCompanion.Decision.peek(signalActor).lastThreatBandRank
SurvivorCompanion.Decision.update(signalActor, signalPlayer, signalRuntime)
check(SurvivorCompanion.Decision.peek(signalActor).nextThreatWarningAt
        == continuousWarningDeadline
        and SurvivorCompanion.Decision.peek(signalActor).lastThreatBandRank
            == continuousWarningRank,
    "elapsed cooldown cannot make one continuous visible threat episode look newly spotted")
SurvivorCompanion.Senses.refreshImmediate = savedSignalRefreshImmediate
SurvivorCompanion.Senses.snapshot = savedSignalSnapshot
end
SurvivorCompanion.__testNeedsAndCamp()
SurvivorCompanion.__testNeedsAndCamp = nil

do
local caredPart = bodyPart({ name = "Hand_L", isBleeding = true, isScratched = true })
local caredActor = actor("sc-relationship-care", 0, 2, { body = bodyDamage(50, { caredPart }) })
registry[caredActor.id] = caredActor
check(not SurvivorCompanion.Commands.observeRelationship(caredActor, player, {
    pressure = 0, immediateCount = 0, player = { danger = 0 },
}), "first relationship observation establishes a baseline without inventing an event")
clock = clock + 1000
caredActor.body.health = 65
caredActor.body.parts = {}
check(SurvivorCompanion.Commands.observeRelationship(caredActor, player, {
    pressure = 0, immediateCount = 0, player = { danger = 0 },
}) and SurvivorCompanion.Commands.peek(caredActor).trust >= 5
    and SurvivorCompanion.Commands.peek(caredActor).memories[#SurvivorCompanion.Commands.peek(caredActor).memories].kind == "treatment",
    "nearby native health improvement becomes a bounded care memory and grows trust")
check(SurvivorCompanion.Commands.conversation(caredActor.id, "memory", player)
    and string.find(caredActor.lastSpeech, "patched", 1, true) ~= nil,
    "structured care memory is rendered as human dialogue")
end

function SurvivorCompanion.__testCharacterDepth()
local Background = SurvivorCompanion.Background
local Personality = SurvivorCompanion.Personality
local PersonalItems = SurvivorCompanion.PersonalItems
local Objectives = SurvivorCompanion.Objectives
local Journal = SurvivorCompanion.Journal

local backgroundA = Background.initialize("sc-background-deterministic", {})
local backgroundB = Background.initialize("sc-background-deterministic", {})
check(backgroundA.profession == backgroundB.profession
    and backgroundA.aptitude == backgroundB.aptitude
    and backgroundA.professionId == "base:" .. backgroundA.profession,
    "companion background is deterministic and uses a vanilla Build 42 profession id")
local lumberjackJogger = Background.initialize("explicit-background", {
    profession = "lumberjack", aptitude = "jogger",
})
check(Background.professionLabel(lumberjackJogger) == "Lumberjack"
    and Background.aptitudeLabel(lumberjackJogger) == "Jogger"
    and Background.preferredRole(lumberjackJogger) == "builder"
    and Background.decisionModifier(lumberjackJogger, "combat") == 2
    and Background.decisionModifier(lumberjackJogger, "retreat") == 2
    and Background.objectiveModifier(lumberjackJogger, "improve_shelter") == 26
    and Background.baseJobModifier(lumberjackJogger, "build") == 5
    and string.find(Background.historyText(lumberjackJogger), "logging crews", 1, true) ~= nil,
    "profession and aptitude independently influence role, choices, goals, work, and history")

local oldResourceLocation, oldCharacterProfession = ResourceLocation, CharacterProfession
local oldProfessionDefinition, oldCharacterTrait, oldPerks = CharacterProfessionDefinition,
    CharacterTrait, Perks
local professionObject = { id = "base:lumberjack" }
local professionTrait, aptitudeTrait = { id = "base:axeman" }, { id = "base:jogger" }
local grantedTraits = { professionTrait }
function grantedTraits:size() return #self end
function grantedTraits:get(index) return self[index + 1] end
ResourceLocation = { of = function(id) return id end }
CharacterProfession = { get = function(id) return id == "base:lumberjack" and professionObject or nil end }
-- Every trait id resolves, so band and character traits really reach the actor
-- and can be read back the way the character sheet reads them.
local traitObjects = { ["base:jogger"] = aptitudeTrait }
CharacterTrait = { get = function(id)
    if type(id) ~= "string" then return nil end
    if traitObjects[id] == nil then
        traitObjects[id] = { id = id, getName = function() return id end }
    end
    return traitObjects[id]
end }
CharacterProfessionDefinition = { getCharacterProfessionDefinition = function(profession)
    if profession ~= professionObject then return nil end
    return {
        getGrantedTraits = function() return grantedTraits end,
    }
end }
Perks = { Axe = "Axe", Strength = "Strength", Maintenance = "Maintenance",
    Sprinting = "Sprinting", Fitness = "Fitness", Nimble = "Nimble",
    Cooking = "Cooking", SmallBlade = "SmallBlade" }
local descriptor = { profession = nil }
function descriptor:setCharacterProfession(profession) self.profession = profession end
function descriptor:getCharacterProfession() return self.profession end
function descriptor:setProfessionSkills() self.skillsSet = true end
local known = { rows = {}, set = {} }
function known:add(trait) self.rows[#self.rows + 1] = trait; self.set[trait] = true; return true end
function known:size() return #self.rows end
function known:get(index) return self.rows[index + 1] end
local nativeBackgroundActor = { levels = {}, traits = known }
function nativeBackgroundActor:getDescriptor() return descriptor end
function nativeBackgroundActor:getCharacterTraits()
    return { getKnownTraits = function() return known end }
end
function nativeBackgroundActor:hasTrait(trait) return known.set[trait] == true end
function nativeBackgroundActor:modifyTraitXPBoost() return true end
function nativeBackgroundActor:getPerkLevel(perk) return self.levels[perk] or 0 end
function nativeBackgroundActor:setPerkLevelDebug(perk, level) self.levels[perk] = level end
function nativeBackgroundActor:applyProfessionRecipes() self.professionRecipes = true end
function nativeBackgroundActor:applyCharacterTraitsRecipes() self.traitRecipes = true end
local nativeApplied, nativeReason = Background.applyNative(nativeBackgroundActor, lumberjackJogger)
check(nativeApplied and nativeReason == "native_background_applied"
    and descriptor.profession == professionObject and descriptor.skillsSet == true
    and nativeBackgroundActor:hasTrait(professionTrait)
    and nativeBackgroundActor:hasTrait(aptitudeTrait)
    and nativeBackgroundActor.levels.Axe == 2
    and nativeBackgroundActor.professionRecipes and nativeBackgroundActor.traitRecipes,
    "native background application assigns profession, traits, recipes, and conservative skills")

local lumberjackAbilities = Background.abilities(lumberjackJogger)
check((nativeBackgroundActor.levels.Strength or 0) == lumberjackAbilities.Strength
        and (nativeBackgroundActor.levels.Fitness or 0) == lumberjackAbilities.Fitness
        and (nativeBackgroundActor.levels.Nimble or 0) == lumberjackAbilities.Nimble
        and (nativeBackgroundActor.levels.Sprinting or 0) == lumberjackAbilities.Sprinting,
    "the four ability scores reach the actor exactly as the background rolled them")

-- Build 42.20.4 seeds Strength and Fitness at 5 during character creation, and
-- getClimbingFailChanceFloat is int(sqrt(2*Fitness + 2*Strength + 2*Nimble -
-- moodle penalties)). A companion left at 0/0 scores 0, which
-- ClimbOverWallState.setParams turns into an unconditional climb failure once
-- any heavy-load moodle is present. 24 of the 31 backgrounds name neither perk,
-- so the baseline has to come from the seed rather than from the skill map.
local cookOrganized = Background.initialize("explicit-background", {
    profession = "burgerflipper", aptitude = "organized",
})
local cookProfession = { id = "base:burgerflipper" }
local organizedTrait = { id = "base:organized" }
CharacterProfession = { get = function(id)
    return id == "base:burgerflipper" and cookProfession or nil
end }
traitObjects["base:organized"] = organizedTrait
CharacterProfessionDefinition = { getCharacterProfessionDefinition = function() return nil end }
local cookDescriptor = { profession = nil }
function cookDescriptor:setCharacterProfession(profession) self.profession = profession end
function cookDescriptor:getCharacterProfession() return self.profession end
function cookDescriptor:setProfessionSkills() self.skillsSet = true end
local cookKnown = { rows = {}, set = {} }
function cookKnown:add(trait) self.rows[#self.rows + 1] = trait; self.set[trait] = true; return true end
local cookActor = { levels = {} }
function cookActor:getDescriptor() return cookDescriptor end
function cookActor:getCharacterTraits() return { getKnownTraits = function() return cookKnown end } end
function cookActor:hasTrait(trait) return cookKnown.set[trait] == true end
function cookActor:modifyTraitXPBoost() return true end
function cookActor:getPerkLevel(perk) return self.levels[perk] or 0 end
function cookActor:setPerkLevelDebug(perk, level) self.levels[perk] = level end
function cookActor:applyProfessionRecipes() self.professionRecipes = true end
function cookActor:applyCharacterTraitsRecipes() self.traitRecipes = true end
local cookApplied, cookReason = Background.applyNative(cookActor, cookOrganized)
local cookAbilities = Background.abilities(cookOrganized)
check(cookApplied and cookReason == "native_background_applied"
    and (cookActor.levels.Strength or 0) == cookAbilities.Strength
    and (cookActor.levels.Fitness or 0) == cookAbilities.Fitness
    and cookActor.levels.Cooking == 2 and cookActor.levels.SmallBlade == 1,
    "a background naming neither physical perk still receives scored abilities")

-- Ability scores and character traits
do
    -- No companion may spawn unable to cross a fence. Build 42.20.4 scores a
    -- climb as int(sqrt(2*Fitness + 2*Strength + 2*Nimble - penalties)), and
    -- ClimbOverWallState.setParams turns a 0 there plus any heavy-load moodle
    -- into an unconditional failure -- a survivor stranded by the first fence.
    local floorHeld, varied, seen = true, false, {}
    local first
    for index = 1, 40 do
        local background = Background.initialize("ability-spread-" .. index, {})
        local scores = Background.abilities(background)
        if scores.Strength < 3 or scores.Fitness < 3 then floorHeld = false end
        if scores.Strength > 10 or scores.Fitness > 10
            or scores.Nimble > 10 or scores.Sprinting > 10 then floorHeld = false end
        local signature = scores.Strength .. ":" .. scores.Fitness
            .. ":" .. scores.Nimble .. ":" .. scores.Sprinting
        first = first or signature
        if signature ~= first then varied = true end
        seen[signature] = true
    end
    check(floorHeld, "every rolled companion stays inside the climbable ability range")
    check(varied, "companions do not all roll the same ability scores")

    local stable = Background.initialize("ability-stability", {})
    local once, twice = Background.abilities(stable), Background.abilities(stable)
    check(once.Strength == twice.Strength and once.Fitness == twice.Fitness
            and once.Nimble == twice.Nimble and once.Sprinting == twice.Sprinting,
        "a companion rolls the same ability scores every time they are asked for")
    -- Character traits are reproduced from the persisted seed rather than
    -- stored, so a reload must roll the same person from the same record.
    local reloaded = Background.initialize("a-different-identity-entirely", stable)
    local beforeTraits, afterTraits = "", ""
    for _, entry in ipairs((Background.characterTraits(stable))) do
        beforeTraits = beforeTraits .. entry.id .. ","
    end
    for _, entry in ipairs((Background.characterTraits(reloaded))) do
        afterTraits = afterTraits .. entry.id .. ","
    end
    check(reloaded.abilitySeed == stable.abilitySeed
            and Background.abilities(reloaded).Strength == once.Strength
            and Background.abilities(reloaded).Fitness == once.Fitness
            and afterTraits == beforeTraits,
        "a restored background keeps its own seed instead of rerolling the survivor")

    -- The mapping is Build 42.20.4's own, from XpUpdate.lua's LevelPerk
    -- listener, so the traits the engine reads agree with the levels the mod
    -- writes with setPerkLevelDebug (which does not fire that event).
    check(Background.bandTrait("Strength", 0).id == "base:weak"
            and Background.bandTrait("Strength", 4).id == "base:feeble"
            and Background.bandTrait("Strength", 5) == nil
            and Background.bandTrait("Strength", 7).id == "base:stout"
            and Background.bandTrait("Strength", 10).id == "base:strong"
            and Background.bandTrait("Fitness", 1).id == "base:unfit"
            and Background.bandTrait("Fitness", 9).id == "base:athletic",
        "band traits follow the engine's own level mapping")

    local budgetHeld, mismatchHeld, traitsVaried = true, true, false
    local firstTraits
    for index = 1, 40 do
        local background = Background.initialize("trait-spread-" .. index, {})
        local traits, spent = Background.characterTraits(background)
        if spent > 6 or spent < -6 then budgetHeld = false end
        local signature, chosen = "", {}
        for _, entry in ipairs(traits) do
            signature = signature .. entry.id .. ","
            chosen[entry.id] = true
        end
        if chosen["base:brave"] and chosen["base:cowardly"] then mismatchHeld = false end
        if chosen["base:inconspicuous"] and chosen["base:conspicuous"] then mismatchHeld = false end
        firstTraits = firstTraits or signature
        if signature ~= firstTraits then traitsVaried = true end
    end
    check(budgetHeld, "character traits stay inside the points budget")
    check(mismatchHeld, "mutually exclusive traits are never taken together")
    check(traitsVaried, "companions do not all roll the same character traits")

    local officer = Background.initialize("mismatch-check",
        { profession = "fireofficer", aptitude = "brave" })
    local officerTraits = Background.characterTraits(officer)
    local cowardly = false
    for _, entry in ipairs(officerTraits) do
        if entry.id == "base:cowardly" or entry.id == "base:smoker" then cowardly = true end
    end
    check(not cowardly, "a profession never rolls a trait that contradicts it")

    local sheet = Background.sheet(nativeBackgroundActor, lumberjackJogger)
    local sheetStrength
    for _, entry in ipairs(sheet.abilities) do
        if entry.name == "Strength" then sheetStrength = entry end
    end
    check(sheet.profession == "Lumberjack" and #sheet.abilities == 4
            and sheetStrength ~= nil
            and sheetStrength.level == lumberjackAbilities.Strength,
        "the character sheet reports the live actor's ability scores")

    -- The band trait the engine derives from a level, and this companion's own
    -- rolled traits, both have to actually reach the actor: the sheet reads the
    -- actor back, so anything it shows is something the engine can also see.
    local expectedBand = Background.bandTrait("Strength", lumberjackAbilities.Strength)
    local rolled = Background.characterTraits(lumberjackJogger)
    local onActor = {}
    for _, trait in ipairs(sheet.traits) do onActor[trait.id] = true end
    local rolledPresent = #rolled == 0
    for _, entry in ipairs(rolled) do
        if onActor[entry.id] then rolledPresent = true end
    end
    check((expectedBand == nil or onActor[expectedBand.id] == true) and rolledPresent
            and sheetStrength.band == (expectedBand and expectedBand.label or nil),
        "band traits and rolled character traits are applied to the actor, not just computed")
    check(Background.traitLabel("base:thickskinned") == "Thick Skinned"
            and Background.traitLabel("base:strong") == "Strong"
            and Background.traitLabel("base:jogger") == "Jogger"
            and Background.traitLabel("base:unmapped") == "Unmapped",
        "every trait on the sheet reads as words rather than a script id")
end

ResourceLocation, CharacterProfession = oldResourceLocation, oldCharacterProfession
CharacterProfessionDefinition, CharacterTrait, Perks = oldProfessionDefinition,
    oldCharacterTrait, oldPerks

local profileA = Personality.initialize("sc-depth-deterministic",
    { occupation = "mechanic", home = "rosewood" })
local profileB = Personality.initialize("sc-depth-deterministic",
    { occupation = "mechanic", home = "rosewood" })
check(profileA.archetype == profileB.archetype
    and profileA.courage == profileB.courage
    and profileA.caution == profileB.caution
    and profileA.compassion == profileB.compassion
    and profileA.practicality == profileB.practicality,
    "personality profile is deterministic for a stable identity and background")
local primaryValues = {
    brave = profileA.courage,
    cautious = profileA.caution,
    caring = profileA.compassion,
    practical = profileA.practicality,
}
local primary = primaryValues[profileA.archetype]
check(primary >= 76 and primary > math.max(
    profileA.archetype == "brave" and -1 or profileA.courage,
    profileA.archetype == "cautious" and -1 or profileA.caution,
    profileA.archetype == "caring" and -1 or profileA.compassion,
    profileA.archetype == "practical" and -1 or profileA.practicality),
    "generated personality has a bounded deterministic primary lead")

local brave = { version = 1, archetype = "brave", courage = 100, caution = 0,
    compassion = 50, practicality = 50 }
local cautious = { version = 1, archetype = "cautious", courage = 0, caution = 100,
    compassion = 50, practicality = 50 }
local braveCombat = Personality.adjustDecision(brave, { kind = "combat" }, {})
local cautiousCombat = Personality.adjustDecision(cautious, { kind = "combat" }, {})
local braveRetreat = Personality.adjustDecision(brave, { kind = "retreat" }, {})
local cautiousRetreat = Personality.adjustDecision(cautious, { kind = "retreat" }, {})
check(braveCombat > cautiousCombat and cautiousRetreat > braveRetreat
    and math.abs(braveCombat) <= 8 and math.abs(cautiousRetreat) <= 8,
    "brave/cautious soft preferences are monotonic and capped")
check(Personality.overrunThresholdDelta(brave, { escapeCount = 2, support = 1 }) <= 4
    and Personality.overrunThresholdDelta(cautious, { escapeCount = 2, support = 1 }) >= -4
    and Personality.overrunThresholdDelta(brave, { escapeCount = 0, support = 1 }) <= 0,
    "personality overrun threshold delta is capped and cannot reward a missing exit")

local satisfiedActor = actor("sc-objective-filter", 1, 4, { inventory = inventory({
    item("Base.Bandage", "Item"), item("Base.RippedSheets", "Item"),
    item("Base.Book", "Literature", { pages = 200 }),
    item("Base.Axe", "Weapon", { condition = 9, conditionMax = 10 }),
}) })
registry[satisfiedActor.id] = satisfiedActor
local satisfiedPossessions = PersonalItems.ensure(satisfiedActor, nil)
local satisfiedState = {
    personalityProfile = { archetype = "practical", courage = 50, caution = 50,
        compassion = 50, practicality = 100 },
    background = { occupation = "mechanic" }, possessions = satisfiedPossessions,
    objectives = { version = 1, serial = 0, history = {}, nextEligibleAt = 0 },
}
Objectives.initialize(satisfiedActor, satisfiedState)
check(satisfiedState.objectives.active.kind ~= "keep_medical_ready"
    and satisfiedState.objectives.active.kind ~= "find_something_to_read"
    and satisfiedState.objectives.active.kind ~= "put_gear_in_order"
    and satisfiedState.objectives.active.kind ~= "recover_keepsake",
    "objective generation filters inventory and keepsake goals that are already satisfied")
registry[satisfiedActor.id] = nil

local depthActor = actor("sc-character-depth", 2, 4, { inventory = inventory() })
registry[depthActor.id] = depthActor
local possessions, assignmentReason = PersonalItems.ensure(depthActor, nil)
local keepsake = possessions and possessions.keepsake
local keepsakeItem = keepsake and PersonalItems.find(depthActor, keepsake.key) or nil
check(possessions ~= nil and assignmentReason == "personal_item_assigned"
    and keepsakeItem ~= nil and keepsakeItem:isFavorite()
    and PersonalItems.personalRecord(keepsakeItem).ownerId == depthActor.id,
    "personal item assignment creates and verifies one favourite owned keepsake")
local beforeEnsureCount = #depthActor.inventory.items
local possessionsAgain = PersonalItems.ensure(depthActor, possessions)
check(possessionsAgain ~= nil and #depthActor.inventory.items == beforeEnsureCount,
    "personal item normalization is idempotent and does not duplicate the keepsake")
local rejectingInventory = inventory()
function rejectingInventory:AddItem() error("injected item-script rejection") end
local optionalKeepsakeActor = actor("sc-optional-keepsake", 2, 5, {
    inventory = rejectingInventory,
})
registry[optionalKeepsakeActor.id] = optionalKeepsakeActor
local optionalPossessions, optionalReason = PersonalItems.ensure(optionalKeepsakeActor, nil)
check(optionalPossessions ~= nil and optionalPossessions.keepsake == nil
    and string.find(optionalReason, "personal_item_deferred:", 1, true) == 1,
    "optional keepsake rejection cannot roll back an otherwise healthy companion")
registry[optionalKeepsakeActor.id] = nil
check(PersonalItems.isProtected(keepsakeItem, depthActor, "craft_material")
    and PersonalItems.isProtected(keepsakeItem, depthActor, "medical_consume")
    and not PersonalItems.isProtected(keepsakeItem, depthActor, "read")
    and not PersonalItems.isProtected(keepsakeItem, depthActor, "repair")
    and not PersonalItems.isProtected(keepsakeItem, depthActor, "transactional_move"),
    "personal item protection blocks automated consumption but permits reading, repair, and manual movement")
local rejectedMarker = item("Base.RejectedMemento", "Item", { rejectSetFavorite = true })
local rejected, rejectedReason = PersonalItems.restoreMarker(rejectedMarker, {
    ownerId = depthActor.id, key = depthActor.id .. ":keepsake:rejected", kind = "memento",
}, true)
check(not rejected and rejectedReason == "personal_favorite_not_retained"
    and PersonalItems.personalRecord(rejectedMarker) == nil,
    "failed favourite verification rolls back a partially written personal marker")

local absoluteSnapshot = {
    threats = {}, immediateAttackers = {}, immediateCount = 3, closeImmediateCount = 3,
    closeThreatCount = 3, occupiedThreatSectors = 3, pressure = 0,
    escapeSquares = { { square = depthActor.square } }, allies = {},
}
check(SurvivorCompanion.Combat.assessOverrun(depthActor, absoluteSnapshot, nil,
        { combatMode = "defensive", personalityProfile = brave }).overrun
    and SurvivorCompanion.Combat.assessOverrun(depthActor, absoluteSnapshot, nil,
        { combatMode = "defensive", personalityProfile = cautious }).overrun,
    "absolute three-attacker/sector overrun remains true for every personality")

local depthState = {
    personality = profileA.archetype,
    personalityProfile = profileA,
    trust = 0, bond = 0, morale = 55, stress = 12,
    memories = {}, care = {},
    background = { occupation = "mechanic", home = "rosewood", value = "loyalty",
        fear = "being_trapped", habit = "checks_tools" },
    reveals = { background = 0, keepsake = false },
    timeTogetherMs = 0,
    possessions = possessions,
    objectives = {
        version = 1, serial = 1, history = {}, nextEligibleAt = 0,
        active = { version = 1, id = depthActor.id .. ":objective:1",
            kind = "share_a_proper_meal", status = "active", revealed = false,
            progress = 0, createdAt = 1 },
    },
}
SurvivorCompanion.Relationship.initialize(depthActor, depthState)
local hiddenJournal = Journal.build(depthActor, depthState, { name = "Depth Fellow" })
check(hiddenJournal.objective.known == false and hiddenJournal.keepsake.known == false
    and #hiddenJournal.background == 0 and depthState.objectives.active.revealed == false,
    "Journal is mutation-free and does not reveal hidden objective, keepsake, or background data")
local reservedSentence, _, reservedChanged = Objectives.respondPlans(depthState)
check(type(reservedSentence) == "string" and reservedChanged == false
    and depthState.objectives.active.revealed == false,
    "plans conversation respects its trust threshold without revealing early")
depthState.trust = 10
local planSentence, _, planChanged = Objectives.respondPlans(depthState)
-- The wording is one varied pool line (clock-salted); every variant names the
-- meal, so the check must not pin a single phrasing.
check(type(planSentence) == "string" and planChanged == true
    and depthState.objectives.active.revealed == true
    and (string.find(planSentence, "meal", 1, true) ~= nil
        or string.find(planSentence, "eat", 1, true) ~= nil),
    "plans conversation reveals exactly the existing objective with personality wording: "
        .. tostring(planSentence))
local revealedJournal = Journal.build(depthActor, depthState, { name = "Depth Fellow" })
check(revealedJournal.objective.known == true
    and revealedJournal.objective.kind == "share_a_proper_meal",
    "Journal reflects an already revealed objective without advancing it")
check(Objectives.noteEvent(depthState, "meal", {})
    and not Objectives.noteEvent(depthState, "meal", {})
    and depthState.objectives.active == nil and #depthState.objectives.history == 1
    and depthState.memories[#depthState.memories].kind == "goal_completed"
    and depthState.care.goalsCompleted == 1,
    "objective completion memory and bounded reward commit exactly once")
local cooldownUntil = depthState.objectives.nextEligibleAt
local _, generatedDuringCooldown = Objectives.initialize(depthActor, depthState)
check(not generatedDuringCooldown and depthState.objectives.active == nil,
    "completed objective cannot regenerate during its six-hour in-game cooldown")
clock = clock + 21600001
local _, generatedAfterCooldown = Objectives.initialize(depthActor, depthState)
check(generatedAfterCooldown and depthState.objectives.active ~= nil
    and depthState.objectives.active.kind ~= "share_a_proper_meal"
    and depthState.objectives.active.createdAt >= cooldownUntil,
    "objective generation resumes after six in-game hours and filters recent repeats")
for serial = 2, 10 do
    depthState.objectives.active = {
        version = 1, id = depthActor.id .. ":objective:" .. tostring(serial),
        kind = "share_a_proper_meal", status = "active", revealed = true,
        progress = 0, createdAt = serial,
    }
    check(Objectives.noteEvent(depthState, "meal", {}),
        "objective history accepts a distinct verified completion")
end
check(#depthState.objectives.history == 8,
    "objective completion history remains capped at eight rows")

do
    local mealActor = actor("sc-capped-meal-objective", 1, 1, { inventory = inventory() })
    mealActor.hunger = 0.6
    local mealMemories = {}
    local mealMemoryCap = tonumber(SurvivorCompanion.GameplayUtil.config("maxMemories")) or 24
    for index = 1, mealMemoryCap do
        mealMemories[index] = { kind = "older_memory", at = clock - index }
    end
    local mealRecord = {
        id = mealActor.id, actor = mealActor, recruited = true,
        state = {
            recruited = true, trust = 10, bond = 10, morale = 55, stress = 12,
            memories = mealMemories, care = {}, reveals = {}, timeTogetherMs = 0,
            objectives = {
                version = 1, serial = 1, history = {}, nextEligibleAt = 0,
                active = { version = 1, id = mealActor.id .. ":objective:1",
                    kind = "share_a_proper_meal", status = "active", revealed = true,
                    progress = 0, createdAt = clock },
            },
        },
    }
    registry[mealActor.id] = mealRecord
    check(SurvivorCompanion.Commands.restore(mealActor, mealRecord),
        "capped-meal fixture restores one companion relationship state")
    local restoredMealState = SurvivorCompanion.Commands.peek(mealActor)
    restoredMealState.memories = mealMemories
    SurvivorCompanion.Commands.observeRelationship(mealActor, player, {})
    clock = clock + 2000
    mealActor.hunger = 0.2
    local mealChanged = SurvivorCompanion.Commands.observeRelationship(mealActor, player, {})
    local mealState = SurvivorCompanion.Commands.peek(mealActor)
    check(mealChanged and #mealState.memories == mealMemoryCap
            and mealState.objectives.active == nil
            and #mealState.objectives.history == 1,
        "a meal event completes exactly once even when capped memories retain the same length: "
            .. tostring(mealChanged) .. "/" .. tostring(#mealState.memories)
            .. "/" .. tostring(mealState.objectives.active)
            .. "/" .. tostring(#mealState.objectives.history))
    SurvivorCompanion.Commands.reset(mealActor)
    registry[mealActor.id] = nil
end

depthState.reveals.background = 2
local publicSummary = SurvivorCompanion.Relationship.summary(depthActor, depthState, {})
check(publicSummary.background.occupation == "Mechanic"
    and string.find(publicSummary.background.history, "old cars", 1, true) ~= nil
    and publicSummary.background.home == nil
    and publicSummary.profession == "Mechanic"
    and type(publicSummary.backgroundLabel) == "string",
    "relationship summary returns only staged revealed background facts")

depthActor.inventory:Remove(keepsakeItem)
local absentPossessions, leftInventory = PersonalItems.observe(depthActor, depthState.possessions)
depthState.possessions = absentPossessions
check(leftInventory and depthState.possessions.keepsake.status == "not_carried",
    "manual keepsake removal remains allowed and is observed as not carried")
local countWhileMissing = #depthActor.inventory.items
local stillMissing = PersonalItems.ensure(depthActor, depthState.possessions)
check(stillMissing.keepsake.status == "not_carried"
    and #depthActor.inventory.items == countWhileMissing,
    "a genuinely absent keepsake is never silently replaced")
depthState.objectives = {
    version = 1, serial = 11, history = {}, nextEligibleAt = 0,
    active = { version = 1, id = depthActor.id .. ":objective:11",
        kind = "recover_keepsake", status = "active", revealed = true,
        progress = 0, createdAt = 11 },
}
local unrelatedPhoto = item("Base.Photo", "Item", { memento = true })
check(Objectives.itemBonus(depthState.objectives, unrelatedPhoto) == 0,
    "same-type unmarked item cannot satisfy the recover-keepsake preference")
depthActor.inventory:AddItem(keepsakeItem)
PersonalItems.reset(depthActor)
depthState.possessions = PersonalItems.observe(depthActor, depthState.possessions)
Objectives.reset(depthActor)
check(Objectives.update(depthActor, depthState)
    and depthState.objectives.active == nil and #depthState.objectives.history == 1,
    "returning the exact marked keepsake completes its objective once")

local privateMeal = item("Base.PrivateMeal", "Food", { hungerChange = -0.4 })
check(PersonalItems.restoreMarker(privateMeal, {
        ownerId = depthActor.id, key = depthActor.id .. ":keepsake:test-meal", kind = "memento",
    }, true), "test personal meal marker is verified")
local hungryActor = actor("sc-protected-needs", 3, 4,
    { inventory = inventory({ privateMeal }) })
hungryActor.hunger = 0.8
registry[hungryActor.id] = hungryActor
local consumedPrivate, privateReason = SurvivorCompanion.Needs.update(hungryActor, player, {
    snapshot = { threats = {}, threatCount = 0, immediateCount = 0, pressure = 0 },
})
check(not consumedPrivate and privateReason == "safe_food_unavailable" and not privateMeal.used,
    "needs automation refuses to consume a marked personal item")
local normalMeal = item("Base.NormalMeal", "Food", { hungerChange = -0.4 })
hungryActor.inventory:AddItem(normalMeal)
check(SurvivorCompanion.Needs.update(hungryActor, player, {
        snapshot = { threats = {}, threatCount = 0, immediateCount = 0, pressure = 0 },
    }) and hungryActor.lastIntent.item == normalMeal,
    "needs automation still selects an ordinary safe item beside a protected one")

registry[depthActor.id] = nil
registry[hungryActor.id] = nil
end
SurvivorCompanion.__testCharacterDepth()
SurvivorCompanion.__testCharacterDepth = nil

local soundsBeforeWhistle = worldSoundCount
check(SurvivorCompanion.Commands.whistle(player) and worldSoundCount == soundsBeforeWhistle + 1,
    "audible whistle command creates exactly one additional world sound")
check(SurvivorCompanion.Commands.handSign(player, "hold") and player.lastEmote == "freeze",
    "visible silent hand sign plays the real player emote")
check(SurvivorCompanion.Commands.handSign(player, "cautious") and player.lastEmote == "followbehind",
    "expanded cautious hand sign uses a validated player emote and command")
check(not SurvivorCompanion.Commands.handSign(player, "invented_signal"),
    "unknown hand sign is rejected instead of guessing an animation")

-- Persistent Base Life contract: zones, classified storage, role-aware jobs
-- and infection restrictions survive a complete export/restore cycle.
function SurvivorCompanion.__testBaseLifeAndCrisis()
local BaseLife = SurvivorCompanion.BaseLife
BaseLife.reset()
local campSquare = cell:getGridSquare(2, 2, 0)
check(BaseLife.create(campSquare, "Test Camp") and BaseLife.active().name == "Test Camp",
    "base core creates one bounded default camp area")
local defaultCampArea = BaseLife.active().zones[1]
check(defaultCampArea and defaultCampArea.x1 == -5 and defaultCampArea.y1 == -5
        and defaultCampArea.x2 == 9 and defaultCampArea.y2 == 9
        and BaseLife.isInside(cell:getGridSquare(9, 2, 0)) == true
        and BaseLife.isInside(cell:getGridSquare(10, 2, 0)) == false,
    "the automatic camp boundary extends seven tiles from its core")
local endpointStarted = BaseLife.beginZone("work", campSquare)
local endpointLocked = endpointStarted
    and BaseLife.lockZoneEndpoint(cell:getGridSquare(4, 5, 0))
local endpointDraft = BaseLife.zoneDraft()
check(endpointStarted and endpointLocked and endpointDraft
        and endpointDraft.first.x == 2 and endpointDraft.first.y == 2
        and endpointDraft.lockedEndpoint.x == 4
        and endpointDraft.lockedEndpoint.y == 5,
    "zone drafting preserves a separately locked mouse endpoint")
BaseLife.cancelZone()
do
    local duck = item("Base.Rubberducky", "Junk")
    local falseDuck = item("Base.KeyRing_RubberDuck", "Junk")
    local duckKeeper = actor("sc-duck-keeper", 2, 2, {
        inventory = inventory({ duck, item("Base.Photo", "Item", { memento = true }) }),
    })
    registry[duckKeeper.id] = duckKeeper
    local commands = SurvivorCompanion.Commands.peek(duckKeeper)
    local desired = SurvivorCompanion.Quirks.itemDesireBonus(duckKeeper, duck, commands)
    local falseDesired = SurvivorCompanion.Quirks.itemDesireBonus(
        duckKeeper, falseDuck, commands)
    local claimed, claimReason = SurvivorCompanion.Quirks.onVerifiedLoot(
        duckKeeper, duck, commands)
    local personal = SurvivorCompanion.PersonalItems.personalRecord(duck)
    local exported = SurvivorCompanion.Commands.export(duckKeeper)
    check(desired > 0 and falseDesired == 0 and claimed
            and claimReason == "duck_devotion_started"
            and personal and personal.ownerId == duckKeeper.id
            and personal.kind == "duck_relic" and duck.favorite == true
            and exported.ritual and exported.ritual.id == "rubber_duck_oracle"
            and exported.ritual.duck.phase == "awaiting_base"
            and SurvivorCompanion.PersonalItems.isProtected(
                duck, duckKeeper, "ordinary_transfer"),
        "only the exact rubber duck becomes a persistent protected personal relic")

    local femaleWalker = zombie(5, 2, {})
    function femaleWalker:isFemale() return true end
    local recognition = SurvivorCompanion.Quirks.recognitionCandidate(
        duckKeeper, femaleWalker, {
            threats = { { actor = femaleWalker } }, threatCount = 1,
            immediateAttackers = {}, immediateCount = 0, pressure = 0.2,
        }, commands, clock, true)
    check(recognition and recognition.arguments[2] == "she"
            and recognition.arguments[5] == "her"
            and SurvivorCompanion.Quirks.speakRecognition(
                duckKeeper, recognition, commands, clock)
            and (SurvivorCompanion.Dialogue.lastSpokenTopic(duckKeeper)
                == "recognition.local"),
        "a forced lone-walker recognition uses the zombie's gendered pronouns and dialogue pool")

    local savedRequest = SurvivorCompanion.Navigation.request
    SurvivorCompanion.Navigation.request = function(subject, target)
        local old = subject.square
        if old and type(old.moving) == "table" then
            for index, value in ipairs(old.moving) do
                if value == subject then table.remove(old.moving, index) break end
            end
        end
        subject.square = target
        target.moving[#target.moving + 1] = subject
        return true, "ritual_test_arrived"
    end
    local safeSnapshot = { threats = {}, threatCount = 0, immediateAttackers = {},
        immediateCount = 0, pressure = 0, player = { danger = 0 } }
    local runtime = { snapshot = safeSnapshot }
    local intent = SurvivorCompanion.Quirks.ritualIntent(
        duckKeeper, nil, safeSnapshot, commands)
    for _ = 1, 10 do
        clock = clock + 2000
        SurvivorCompanion.Quirks.updateRitual(duckKeeper, nil, runtime, intent)
        if commands.ritual.duck.phase == "carried"
            and commands.ritual.completions == 1 then break end
    end
    check(commands.ritual.completions == 1
            and commands.ritual.duck.phase == "carried"
            and duckKeeper.inventory:contains(duck)
            and #duckKeeper.square.worldItems == 0
            and SurvivorCompanion.Journal.build(duckKeeper, commands, {}).ritual.known,
        "duck worship places, addresses, and retrieves the exact relic without duplication")

    commands.ritual.duck.phase = "awaiting_base"
    SurvivorCompanion.Commands.persist(duckKeeper)
    intent = SurvivorCompanion.Quirks.ritualIntent(
        duckKeeper, nil, safeSnapshot, commands)
    for _ = 1, 5 do
        clock = clock + 2000
        SurvivorCompanion.Quirks.updateRitual(duckKeeper, nil, runtime, intent)
        if commands.ritual.duck.phase == "displayed" then break end
    end
    local displayedWorld = duckKeeper.square.worldItems[1]
    local interrupted = SurvivorCompanion.Quirks.interrupt(duckKeeper, "test_alarm")
    local recovery = SurvivorCompanion.Quirks.ritualIntent(
        duckKeeper, nil, safeSnapshot, commands)
    for _ = 1, 5 do
        clock = clock + 2000
        SurvivorCompanion.Quirks.updateRitual(duckKeeper, nil, runtime, recovery)
        if commands.ritual.duck.phase == "carried" then break end
    end
    check(displayedWorld and displayedWorld.item == duck and interrupted
            and recovery and recovery.recovery == true
            and commands.ritual.duck.phase == "carried"
            and duckKeeper.inventory:contains(duck)
            and #duckKeeper.square.worldItems == 0,
        "an interrupted duck shrine persists recovery_pending and later recovers the same object")
    SurvivorCompanion.Navigation.request = savedRequest
    for index, value in ipairs(duckKeeper.square.moving) do
        if value == duckKeeper then table.remove(duckKeeper.square.moving, index) break end
    end
    SurvivorCompanion.Quirks.reset(duckKeeper)
    SurvivorCompanion.Commands.reset(duckKeeper)
    registry[duckKeeper.id] = nil
end
do
    local relic = item("Base.Rubberducky", "Junk")
    local seeker = actor("sc-duck-search", 2, 2, {
        inventory = inventory({ relic }), square = campSquare,
    })
    registry[seeker.id] = seeker
    local commands = SurvivorCompanion.Commands.peek(seeker)
    SurvivorCompanion.Quirks.onVerifiedLoot(seeker, relic, commands)
    local relicKey = SurvivorCompanion.PersonalItems.personalRecord(relic).key
    campSquare.worldItems = {}
    for index = 1, 64 do
        campSquare:AddWorldInventoryItem(
            item("Base.SearchClutter" .. tostring(index), "Junk"), 0.5, 0.5, 0, false)
    end
    local dropped, relicWorld = SurvivorCompanion.GameplayUtil.dropItem(
        seeker.inventory, campSquare, relic, 0.5, 0.5, 0)
    commands.ritual.duck.phase = "recovery_pending"
    commands.ritual.duck.x, commands.ritual.duck.y, commands.ritual.duck.z =
        campSquare.x, campSquare.y, campSquare.z
    local safeSnapshot = { threats = {}, threatCount = 0, immediateAttackers = {},
        immediateCount = 0, pressure = 0, player = { danger = 0 } }
    local runtime = { snapshot = safeSnapshot }
    local recovery = SurvivorCompanion.Quirks.ritualIntent(
        seeker, nil, safeSnapshot, commands)
    local firstSearch, firstSearchReason = SurvivorCompanion.Quirks.updateRitual(
        seeker, nil, runtime, recovery)
    check(dropped and relicWorld == campSquare.worldItems[65]
            and firstSearch and firstSearchReason == "duck_relic_search_pending"
            and commands.ritual.duck.phase == "recovery_pending"
            and commands.ritual.duck.x == campSquare.x,
        "an exact relic beyond the first 64 wrappers remains pending with its saved location")
    local searchInterrupted = SurvivorCompanion.Quirks.interrupt(
        seeker, "test_search_interruption")
    recovery = SurvivorCompanion.Quirks.ritualIntent(
        seeker, nil, safeSnapshot, commands)
    check(searchInterrupted and recovery and recovery.recovery == true
            and commands.ritual.duck.phase == "recovery_pending"
            and commands.ritual.duck.x == campSquare.x,
        "interrupting an incomplete relic search preserves its recovery evidence")

    -- Move the unvisited relic behind the cursor once. The first pass can no
    -- longer prove absence; the stable verification pass must rediscover it.
    table.remove(campSquare.worldItems, 65)
    table.insert(campSquare.worldItems, 1, relicWorld)
    local reorderedSearch, reorderedReason = SurvivorCompanion.Quirks.updateRitual(
        seeker, nil, runtime, recovery)
    check(reorderedSearch and reorderedReason == "duck_relic_search_pending"
            and commands.ritual.duck.phase == "recovery_pending"
            and commands.ritual.duck.x == campSquare.x,
        "a relic crossing the cursor during collection reorder is not declared lost")
    for _ = 1, 10 do
        clock = clock + 2000
        SurvivorCompanion.Quirks.updateRitual(seeker, nil, runtime, recovery)
        if commands.ritual.duck.phase == "carried" then break end
    end
    check(commands.ritual.duck.phase == "carried"
            and seeker.inventory:contains(relic)
            and SurvivorCompanion.PersonalItems.personalRecord(relic).key == relicKey
            and #campSquare.worldItems == 64,
        "the verification pass recovers the original reordered 65th relic without duplication")

    local holding = inventory()
    seeker.inventory:Remove(relic)
    holding:AddItem(relic)
    commands.ritual.duck.phase = "recovery_pending"
    commands.ritual.duck.x, commands.ritual.duck.y, commands.ritual.duck.z = 400, 400, 0
    recovery = SurvivorCompanion.Quirks.ritualIntent(
        seeker, nil, safeSnapshot, commands)
    local unavailable, unavailableReason = SurvivorCompanion.Quirks.updateRitual(
        seeker, nil, runtime, recovery)
    check(not unavailable and unavailableReason == "duck_relic_search_unavailable"
            and commands.ritual.duck.phase == "recovery_pending"
            and commands.ritual.duck.x == 400,
        "an unloaded relic square preserves recovery state and coordinates")

    local missingSquare = makeSquare(42, -8, 0)
    commands.ritual.duck.x, commands.ritual.duck.y, commands.ritual.duck.z =
        missingSquare.x, missingSquare.y, missingSquare.z
    recovery = SurvivorCompanion.Quirks.ritualIntent(
        seeker, nil, safeSnapshot, commands)
    local missingPending, missingPendingReason = SurvivorCompanion.Quirks.updateRitual(
        seeker, nil, runtime, recovery)
    check(missingPending and missingPendingReason == "duck_relic_search_pending"
            and commands.ritual.duck.phase == "recovery_pending"
            and commands.ritual.duck.x == missingSquare.x,
        "one complete empty relic pass is still pending rather than proof of loss")
    local missing, missingReason = SurvivorCompanion.Quirks.updateRitual(
        seeker, nil, runtime, recovery)
    check(not missing and missingReason == "duck_relic_missing"
            and commands.ritual.duck.phase == "lost"
            and commands.ritual.duck.x == nil,
        "two identical complete passes can establish genuine relic absence")
    campSquare.worldItems = {}
    SurvivorCompanion.Quirks.reset(seeker)
    SurvivorCompanion.Commands.reset(seeker)
    registry[seeker.id] = nil
end
do
    local function faultWorld(mode)
        local sourceItem = item("Base.Rubberducky", "Item")
        local source = inventory({ sourceItem })
        local square = { x = 30, y = 30, z = 0, worldItems = {}, objects = {} }
        function square:getX() return self.x end
        function square:getY() return self.y end
        function square:getZ() return self.z end
        function square:getWorldObjects() return self.worldItems end
        function square:getObjects() return self.objects end
        local worldItem = { item = sourceItem, square = square }
        function worldItem:getItem() return self.item end
        function worldItem:getSquare() return self.square end
        function worldItem:setSquare(target) self.square = target end
        local function injected()
            if mode == "throw" then error("injected world removal failure") end
            return false
        end
        square.transmitRemoveItemFromSquare = injected
        square.removeWorldObject = injected
        worldItem.removeFromWorld = injected
        worldItem.removeFromSquare = injected
        square.worldItems[1], square.objects[1] = worldItem, worldItem
        sourceItem.worldItem = worldItem
        return worldItem, sourceItem, source, square
    end
    for _, mode in ipairs({ "noop", "throw" }) do
        local worldItem, sourceItem, source, square = faultWorld(mode)
        local destination = inventory()
        local recovered, reason = SurvivorCompanion.GameplayUtil.takeWorldItemVerified(
            worldItem, destination, sourceItem)
        check(not recovered and reason == "world_item_remove_failed_rolled_back"
                and not destination:contains(sourceItem) and source:contains(sourceItem)
                and square.worldItems[1] == worldItem and square.objects[1] == worldItem
                and sourceItem:getWorldItem() == worldItem,
            "a " .. mode .. " native removal cannot report pickup while the world owner remains")
    end

    local rejectSquare = cell:getGridSquare(12, -8, 0)
    rejectSquare.worldItems = {}
    local rejectItem = item("Base.Rubberducky", "Item")
    local rejectSource = inventory({ rejectItem })
    local dropped, rejectWorld = SurvivorCompanion.GameplayUtil.dropItem(
        rejectSource, rejectSquare, rejectItem, 0.5, 0.5, 0)
    local rejectingDestination = inventory()
    rejectingDestination.rejectAdd = true
    local rejected, rejectReason, rejectDetails =
        SurvivorCompanion.GameplayUtil.takeWorldItemVerified(
            rejectWorld, rejectingDestination, rejectItem)
    check(dropped and not rejected and rejectReason == "pickup_add_failed_rolled_back"
            and rejectDetails and rejectDetails.worldPresent == true
            and not rejectingDestination:contains(rejectItem)
            and #rejectSquare.worldItems == 1
            and rejectItem:getWorldItem() == rejectSquare.worldItems[1],
        "a destination rejection reconstructs and verifies exactly one world owner")

    local rollbackItem = item("Base.Rubberducky", "Item")
    local rollbackSource = inventory({ rollbackItem })
    local rollbackSquare = { x = 31, y = 30, z = 0, worldItems = {}, objects = {} }
    function rollbackSquare:getWorldObjects() return self.worldItems end
    function rollbackSquare:getObjects() return self.objects end
    local rollbackWorld = { item = rollbackItem, square = rollbackSquare }
    function rollbackWorld:getItem() return self.item end
    function rollbackWorld:getSquare() return self.square end
    function rollbackWorld:setSquare(target) self.square = target end
    local function removeRollbackWorld()
        rollbackSquare.worldItems, rollbackSquare.objects = {}, {}
        rollbackWorld.square = nil
    end
    function rollbackSquare:transmitRemoveItemFromSquare() removeRollbackWorld() end
    function rollbackSquare:removeWorldObject() removeRollbackWorld() end
    function rollbackWorld:removeFromWorld() end
    function rollbackWorld:removeFromSquare() removeRollbackWorld() end
    function rollbackSquare:AddWorldInventoryItem() return nil end
    rollbackSquare.worldItems[1], rollbackSquare.objects[1] = rollbackWorld, rollbackWorld
    rollbackItem.worldItem = rollbackWorld
    local rollbackDestination = inventory()
    rollbackDestination.rejectAdd = true
    local rollbackAccepted, rollbackReason, rollbackDetails =
        SurvivorCompanion.GameplayUtil.takeWorldItemVerified(
            rollbackWorld, rollbackDestination, rollbackItem)
    check(not rollbackAccepted and rollbackReason == "pickup_rollback_failed"
            and rollbackDetails and rollbackDetails.sourcePreserved == true
            and rollbackSource:contains(rollbackItem)
            and not rollbackDestination:contains(rollbackItem)
            and #rollbackSquare.worldItems == 0 and rollbackItem:getWorldItem() == nil,
        "failed world reconstruction preserves one explicit source owner and reports failure")

    local idempotentSquare = cell:getGridSquare(11, -8, 0)
    idempotentSquare.worldItems = {}
    local idempotentItem = item("Base.Rubberducky", "Item")
    local idempotentSource, idempotentDestination = inventory({ idempotentItem }), inventory()
    local idempotentDropped, idempotentWorld = SurvivorCompanion.GameplayUtil.dropItem(
        idempotentSource, idempotentSquare, idempotentItem, 0.5, 0.5, 0)
    local firstPickup = SurvivorCompanion.GameplayUtil.takeWorldItemVerified(
        idempotentWorld, idempotentDestination, idempotentItem)
    local secondPickup, secondReason = SurvivorCompanion.GameplayUtil.takeWorldItemVerified(
        idempotentWorld, idempotentDestination, idempotentItem)
    check(idempotentDropped and firstPickup and secondPickup
            and secondReason == "already_recovered"
            and idempotentDestination:contains(idempotentItem)
            and #idempotentSquare.worldItems == 0
            and idempotentItem:getWorldItem() == nil,
        "repeated exact pickup is idempotent after one verified ownership transfer")

    -- Native IsoGridSquare objects do not expose the permissive worldItems
    -- table used by the main fixture. Keep authoritative collections private so
    -- this exercises the production tri-state helper without that escape hatch.
    local membershipSquare = { nativeWorld = {}, nativeObjects = {} }
    function membershipSquare:getWorldObjects() return self.nativeWorld end
    function membershipSquare:getObjects() return self.nativeObjects end
    local membershipWorld = {}
    membershipSquare.nativeWorld[1] = membershipWorld
    check(SurvivorCompanion.GameplayUtil.worldItemPresent(
            membershipSquare, membershipWorld) == true,
        "native-shaped world membership reports the exact wrapper as present")
    membershipSquare.nativeWorld, membershipSquare.nativeObjects = {}, {}
    check(SurvivorCompanion.GameplayUtil.worldItemPresent(
            membershipSquare, membershipWorld) == false,
        "native-shaped readable empty collections prove exact wrapper absence")
    function membershipSquare:getWorldObjects() error("unreadable world list") end
    function membershipSquare:getObjects() error("unreadable object list") end
    check(SurvivorCompanion.GameplayUtil.worldItemPresent(
            membershipSquare, membershipWorld) == nil,
        "unreadable native-shaped collections preserve unknown membership")

    local function detachedWorldFixture(x, destinationRejects, reconstructionRejects)
        local exact = item("Base.Rubberducky", "Item")
        local target = inventory()
        target.rejectAdd = destinationRejects == true
        local nativeSquare = {
            x = x, y = -8, z = 0, nativeWorld = {}, nativeObjects = {},
        }
        function nativeSquare:getX() return self.x end
        function nativeSquare:getY() return self.y end
        function nativeSquare:getZ() return self.z end
        function nativeSquare:getWorldObjects() return self.nativeWorld end
        function nativeSquare:getObjects() return self.nativeObjects end
        local wrapper = { item = exact, square = nativeSquare }
        function wrapper:getItem() return self.item end
        function wrapper:getSquare() return self.square end
        function wrapper:setSquare(value) self.square = value end
        local function removeExact()
            nativeSquare.nativeWorld, nativeSquare.nativeObjects = {}, {}
            wrapper.square = nil
        end
        function nativeSquare:transmitRemoveItemFromSquare() removeExact() end
        function nativeSquare:removeWorldObject() removeExact() end
        function wrapper:removeFromWorld() self.removedFromWorld = true end
        function wrapper:removeFromSquare() removeExact() end
        function nativeSquare:AddWorldInventoryItem(added)
            if reconstructionRejects then return nil end
            local restored = { item = added, square = self }
            function restored:getItem() return self.item end
            function restored:getSquare() return self.square end
            function restored:setSquare(value) self.square = value end
            self.nativeWorld[1], self.nativeObjects[1] = restored, restored
            added.worldItem = restored
            return added
        end
        nativeSquare.nativeWorld[1], nativeSquare.nativeObjects[1] = wrapper, wrapper
        exact.worldItem = wrapper
        squares[squareKey(x, -8, 0)] = nativeSquare
        return wrapper, exact, target, nativeSquare
    end

    local nativeWorld, nativeItem, nativeDestination, nativeSquare =
        detachedWorldFixture(40, false, false)
    local nativeRecovered, nativeReason =
        SurvivorCompanion.GameplayUtil.takeWorldItemVerified(
            nativeWorld, nativeDestination, nativeItem)
    check(nativeRecovered and nativeReason == "world_item_recovered"
            and nativeDestination:contains(nativeItem)
            and #nativeSquare.nativeWorld == 0 and #nativeSquare.nativeObjects == 0
            and nativeItem:getWorldItem() == nil,
        "native-shaped pickup leaves exactly one destination-owned original item")

    local pendingWorld, pendingItem, pendingDestination, pendingSquare =
        detachedWorldFixture(41, true, true)
    local pendingRecovered, pendingReason, pendingDetails =
        SurvivorCompanion.GameplayUtil.takeWorldItemVerified(
            pendingWorld, pendingDestination, pendingItem)
    local pendingRecord = SurvivorCompanion.GameplayUtil.pendingWorldRecovery(pendingItem)
    check(not pendingRecovered and pendingReason == "pickup_rollback_failed"
            and pendingDetails and pendingDetails.owner == "managed_recovery"
            and pendingRecord and pendingRecord.item == pendingItem
            and not pendingDestination:contains(pendingItem)
            and #pendingSquare.nativeWorld == 0,
        "failed destination and world reconstruction retain the exact item in managed recovery")
    pendingDestination.rejectAdd = false
    local resumed, resumedReason = SurvivorCompanion.GameplayUtil.takeWorldItemVerified(
        pendingWorld, pendingDestination, pendingItem)
    check(resumed and resumedReason == "world_item_recovered_from_pending"
            and pendingDestination:contains(pendingItem)
            and SurvivorCompanion.GameplayUtil.pendingWorldRecovery(pendingItem) == nil,
        "a repeated pickup resumes managed recovery without replacement or duplication")
end
local protectedArea = BaseLife.active().zones[1]
do
    local fourCorners = {
        { kind = "area", x1 = 0, y1 = 0, x2 = 1, y2 = 1, z = 0 },
        { kind = "area", x1 = 4, y1 = 0, x2 = 5, y2 = 1, z = 0 },
        { kind = "area", x1 = 0, y1 = 4, x2 = 1, y2 = 5, z = 0 },
        { kind = "area", x1 = 4, y1 = 4, x2 = 5, y2 = 5, z = 0 },
    }
    local adjacent = {
        { kind = "area", x1 = 0, y1 = 0, x2 = 2, y2 = 5, z = 0 },
        { kind = "area", x1 = 3, y1 = 0, x2 = 5, y2 = 5, z = 0 },
    }
    local lShape = {
        { kind = "area", x1 = 0, y1 = 0, x2 = 5, y2 = 1, z = 0 },
        { kind = "area", x1 = 0, y1 = 2, x2 = 1, y2 = 5, z = 0 },
    }
    local target = { x1 = 0, y1 = 0, x2 = 5, y2 = 5, z = 0 }
    check(not BaseLife.zoneInsideAreaUnion(target, fourCorners)
            and BaseLife.zoneInsideAreaUnion(target, adjacent)
            and not BaseLife.zoneInsideAreaUnion(target, lShape),
        "zone containment accepts a complete adjacent union and rejects corner islands or an L-shaped hole")
end
local areaStarted = BaseLife.beginZone("area", cell:getGridSquare(1, 1, 0))
local areaFinished, removableArea = BaseLife.finishZone(
    cell:getGridSquare(2, 2, 0), "Temporary extension")
local areaRemoved = areaFinished and BaseLife.removeZone(removableArea.id)
local lastAreaRemoved, lastAreaReason = BaseLife.removeZone(protectedArea.id)
check(areaStarted and areaFinished and areaRemoved
        and not lastAreaRemoved and lastAreaReason == "last_base_area",
    "base zone management can remove an extension but protects the last camp area: "
        .. tostring(areaStarted) .. "/" .. tostring(areaFinished) .. "/"
        .. tostring(areaRemoved) .. "/" .. tostring(lastAreaRemoved) .. "/"
        .. tostring(lastAreaReason))
check(BaseLife.beginZone("quarantine", cell:getGridSquare(1, 1, 0))
    and BaseLife.finishZone(cell:getGridSquare(3, 3, 0), "Quiet room"),
    "two-corner quarantine zoning commits inside the camp boundary")
do
    local extensionX = protectedArea.x2 + 1
    local addedArea, extension = BaseLife.beginZone("area",
        cell:getGridSquare(extensionX, 2, 0))
    if addedArea then addedArea, extension = BaseLife.finishZone(
        cell:getGridSquare(extensionX + 1, 3, 0), "Workshop extension") end
    local addedWork, workZone = BaseLife.beginZone("work",
        cell:getGridSquare(extensionX, 2, 0))
    if addedWork then addedWork, workZone = BaseLife.finishZone(
        cell:getGridSquare(extensionX + 1, 3, 0), "Edge workshop") end
    local removedInUse, inUseReason = false, "missing_extension"
    if extension then removedInUse, inUseReason = BaseLife.removeZone(extension.id) end
    local cleaned = workZone and BaseLife.removeZone(workZone.id)
        and BaseLife.removeZone(extension.id)
    check(addedArea and addedWork and not removedInUse
            and inUseReason == "base_area_in_use" and cleaned,
        "an area cannot be removed while a configured child zone depends on its coverage: "
            .. tostring(addedArea) .. "/" .. tostring(addedWork) .. "/"
            .. tostring(removedInUse) .. "/" .. tostring(inUseReason) .. "/"
            .. tostring(cleaned))
end
